window.COURSES=window.COURSES||{};window.COURSES.bancos={"id":"bancos","name":"Bancos de Dados e SQL","title":"Bancos de Dados e SQL Forge","updated":"2026-10-24","hours":144,"description":"Aprenda modelagem, SQL, integridade, transações e operação antes de escolher um banco. SQLite é o laboratório acessível para praticar os conceitos.","prerequisites":["Nenhuma experiência prévia com banco de dados é exigida.","Computador com SQLite 3.37+ e editor; Python 3.12+ é usado em duas aulas de integração e cópia consistente."],"outcome":"Banco de uma biblioteca com empréstimos, consultas, transações, testes de integridade e plano de recuperação documentado.","extension":"sql","codeLanguage":"sql","setup":[{"title":"Um banco de laboratório","text":"Instale a ferramenta sqlite3 pelo site oficial e confira sqlite3 --version. Ela contém o motor e um cliente de terminal. Use uma pasta por aula. Não confunda SQL com comandos do terminal ou com comandos iniciados por ponto do cliente."},{"title":"Exemplos independentes","text":"Execute sqlite3 :memory: para abrir um banco temporário novo; use .headers off, .mode list e .read aula.sql no prompt. .quit encerra a sessão. As tabelas são criadas pelo próprio exemplo. Para persistir um projeto, abra sqlite3 biblioteca.db em uma pasta dedicada."},{"title":"Conceitos e dialetos","text":"SQL é uma linguagem; SQLite, PostgreSQL e os demais cursos são sistemas que a implementam com diferenças. A base ensina conceitos transferíveis e identifica recursos do laboratório. As aulas Python têm arquivo e comando próprios; o editor da plataforma apenas salva rascunhos."}],"references":[{"title":"SQL no laboratório SQLite","description":"Sintaxe e diferenças do dialeto usado nos exemplos.","url":"https://www.sqlite.org/lang.html"},{"title":"Consultas e conjuntos","description":"SELECT, junções e agrupamento.","url":"https://www.sqlite.org/lang_select.html"},{"title":"Integridade referencial","description":"Chaves, referências e ações de exclusão.","url":"https://www.sqlite.org/foreignkeys.html"},{"title":"Transações","description":"Limites de uma unidade de trabalho.","url":"https://www.sqlite.org/lang_transaction.html"},{"title":"Parâmetros no Python","description":"Binding de valores e conexão com SQLite.","url":"https://docs.python.org/3/library/sqlite3.html"},{"title":"Cópia consistente","description":"Backup online e verificação de restauração.","url":"https://www.sqlite.org/backup.html"}],"levels":[{"id":1,"title":"Primeiros conceitos","tag":"Fundamentos","hours":12,"summary":"Entenda o SGBD, a estrutura das tabelas e as regras que protegem os dados.","skills":["Dados e unidades","DDL e DML","Constraints"],"project":"Catálogo de livros","deliverables":["Arquivo SQL que cria livros com id, título e quantidade.","Cinco registros fictícios e duas consultas ordenadas.","Dicionário com significado, tipo e obrigatoriedade de cada coluna."],"rubric":["IDs duplicados e estoque negativo são rejeitados.","Cada linha representa um único livro.","Consultas esperadas podem ser reproduzidas em um banco novo."],"challenge":[{"question":"Um relatório mostra receita=600 sem unidade. Qual informação falta primeiro?","options":["Um índice em toda coluna.","A senha do administrador.","A definição da medida e sua unidade.","O nome do tema visual."],"answer":2,"explanation":"O mesmo número pode representar medidas diferentes; a modelagem começa pela semântica."},{"question":"Dois SELECT sem ORDER BY retornaram ordens diferentes. Isso prova perda de dados?","options":["Sim, sempre.","Sim, o segundo SELECT apaga linhas.","Não, porque toda tabela é ordenada por título.","Não; ordem não faz parte da garantia dessa consulta."],"answer":3,"explanation":"Dados e sua apresentação são coisas distintas."},{"question":"Um CHECK(preco>=0) aceitou NULL. Qual é a correção se preço é obrigatório?","options":["Adicionar NOT NULL e manter CHECK.","Remover CHECK.","Ordenar por preço.","Trocar SELECT por UPDATE em toda consulta."],"answer":0,"explanation":"Ausência e valor fora do intervalo são problemas distintos."}]},{"id":2,"title":"Modelagem e relacionamentos","tag":"Fundamentos","hours":12,"summary":"Transforme regras do domínio em identidades, cardinalidades e referências.","skills":["Chaves candidatas","1:N","N:N"],"project":"Modelo de biblioteca","deliverables":["Diagrama com livros, autores, leitores e empréstimos.","DDL das tabelas e associações.","Três tentativas inválidas documentadas."],"rubric":["Cada entidade tem identidade estável.","Relação N:N usa associação sem pares duplicados.","Nenhuma FK aceita referência órfã com a verificação ligada."],"challenge":[{"question":"Adicionar um ID substituto torna dispensável a unicidade da matrícula?","options":["Sim, qualquer duplicação vira válida.","Não, a regra de negócio ainda precisa de UNIQUE.","Sim, se a tabela tiver três colunas.","Não, porque ID não pode ser chave."],"answer":1,"explanation":"Identidade técnica e unicidade de negócio atendem objetivos diferentes."},{"question":"Uma conexão nova aceitou leitor inexistente no SQLite. O que conferir?","options":["O tema escuro.","Se ORDER BY foi omitido.","Se foreign_keys foi ativado nessa conexão antes da transação.","Se a tabela tem mais de dez linhas."],"answer":2,"explanation":"A configuração de integridade é uma propriedade da conexão no laboratório."},{"question":"Por que PRIMARY KEY(autor_id) isolada na associação é incorreta?","options":["Porque chaves não podem ser inteiras.","Porque toda tabela exige chave textual.","Porque permitiria só um livro no banco inteiro.","Impediria o mesmo autor de participar de outro livro."],"answer":3,"explanation":"A restrição precisa corresponder à identidade do fato, que é o par."}]},{"id":3,"title":"Consultas essenciais","tag":"Fundamentos","hours":12,"summary":"Consulte as linhas certas, trate ausência e organize resultados previsíveis.","skills":["WHERE","NULL","ORDER BY e LIMIT"],"project":"Busca do catálogo","deliverables":["Consultas de faixa de preço, estado e ausência.","Paginação com desempate e exemplos de duas páginas.","Tabela de casos de fronteira."],"rubric":["Filtros respeitam igualdade nos limites.","Ausência é testada com IS NULL.","Todas as saídas paginadas têm ordem explícita."],"challenge":[{"question":"A regra exige ativo E (barato OU promoção). Qual cuidado é essencial?","options":["Agrupar barato OU promoção com parênteses.","Colocar toda condição entre aspas.","Trocar AND por vírgula.","Excluir o caso na fronteira."],"answer":0,"explanation":"Agrupamento preserva o alcance da exigência de ativo."},{"question":"Trocar toda data ausente por 0 melhora o modelo?","options":["Sim, NULL sempre causa corrupção.","Não; mistura uma ausência com um valor que não é uma data do domínio.","Sim, 0 é a data de hoje.","Não, porque SQL proíbe zero."],"answer":1,"explanation":"Representação precisa preservar o significado de ausência."},{"question":"LIMIT 10 sem ORDER BY define os dez registros mais recentes?","options":["Sim, o motor sempre grava do mais novo para o mais velho.","Sim, LIMIT cria data automaticamente.","Não; é necessário ordenar por um campo de tempo e desempate.","Não, porque LIMIT só permite um registro."],"answer":2,"explanation":"Recência é uma regra de ordenação, não uma consequência de limitar."}]},{"id":4,"title":"Relatórios e indicadores","tag":"Intermediário","hours":12,"summary":"Construa medidas com granularidade definida e filtros no estágio certo.","skills":["GROUP BY","HAVING","CASE"],"project":"Relatório de circulação","deliverables":["Indicadores por categoria e estado.","Definição do numerador e denominador de cada medida.","Dados de teste com NULL e fronteiras."],"rubric":["COUNT(*) e COUNT(coluna) são usados conscientemente.","Cancelamentos são tratados antes da agregação.","Cada classificação cobre as faixas sem sobreposição acidental."],"challenge":[{"question":"Um indicador exige número de linhas, inclusive sem valor. O que usar?","options":["COUNT(valor).","SUM(valor).","AVG(valor).","COUNT(*)."],"answer":3,"explanation":"O asterisco conta linhas sem depender da nulidade de uma coluna."},{"question":"Remover canceladas após somar mantém o mesmo relatório?","options":["Não necessariamente; o filtro deve atuar nas linhas que alimentam a soma.","Sim, filtros nunca mudam somas.","Sim, HAVING sempre conhece cada venda.","Não, porque GROUP BY apaga o banco."],"answer":0,"explanation":"A etapa em que a regra é aplicada altera a medida."},{"question":"Duas condições do CASE incluem o valor 10. Qual saída vence?","options":["A do último WHEN sempre.","A do primeiro WHEN verdadeiro.","As duas saídas são concatenadas.","A consulta escolhe aleatoriamente."],"answer":1,"explanation":"CASE tem prioridade pela ordem das condições."}]},{"id":5,"title":"Junções e existência","tag":"Intermediário","hours":12,"summary":"Relacione tabelas e verifique multiplicidade, ausência e correlação.","skills":["INNER JOIN","LEFT JOIN","EXISTS"],"project":"Relatório de leitores","deliverables":["Consulta de leitores com e sem empréstimo.","Totais que não duplicam medidas do leitor.","Comparação de NOT IN com NULL e NOT EXISTS."],"rubric":["A granularidade de cada relatório é declarada.","Leitores sem movimento aparecem quando solicitado.","Filtros da tabela direita não anulam relações externas sem intenção."],"challenge":[{"question":"Por que somar o saldo de um cliente após juntar três pedidos pode triplicá-lo?","options":["SUM cria novos pedidos.","JOIN soma automaticamente valores.","O saldo do cliente se repete em cada linha do resultado.","Porque todo saldo precisa ser TEXT."],"answer":2,"explanation":"Antes de agregar, confira a granularidade da junção."},{"question":"WHERE e.id>10 preserva leitores sem qualquer empréstimo em um LEFT JOIN?","options":["Sim, LEFT JOIN ignora WHERE.","Sim, NULL é maior que 10.","Só se o nome tiver três letras.","Não; a condição elimina a parte direita nula."],"answer":3,"explanation":"A lógica do filtro deve respeitar a ausência criada pela junção externa."},{"question":"A subconsulta de EXISTS não usa a linha externa. Que pergunta ela responde?","options":["Se existe alguma linha global que atenda ao filtro interno.","Quantos empréstimos cada leitor tem.","Se cada leitor tem uma chave primária.","Se a tabela possui índices únicos."],"answer":0,"explanation":"Sem correlação, o teste não é específico ao leitor."}]},{"id":6,"title":"Qualidade do modelo","tag":"Intermediário","hours":12,"summary":"Reconheça dependências, elimine anomalias e justifique redundância medida.","skills":["Dependências funcionais","Normalização","Reconciliação"],"project":"Revisão do modelo da biblioteca","deliverables":["Modelo antes/depois com dependências.","Exemplos de anomalia de inserção e exclusão.","Consulta de reconciliação de um resumo."],"rubric":["Decomposição preserva a relação por chaves.","Atributos históricos mantêm seu significado.","Qualquer redundância tem política de atualização e reconstrução."],"challenge":[{"question":"O mesmo código de curso tem nomes contraditórios em várias matrículas. Que problema o modelo expõe?","options":["Uma chave estrangeira automaticamente criada.","Redundância de um fato que depende do curso.","Uma melhoria obrigatória de desempenho.","Um efeito inevitável de toda normalização."],"answer":1,"explanation":"O nome do curso deveria ter uma fonte única no modelo."},{"question":"Preço contratado de um item precisa sempre vir do preço atual do produto?","options":["Sim, para normalizar é obrigatório alterar compras antigas.","Sim, toda coluna numérica é redundante.","Não; o preço histórico pertence ao fato da compra.","Não, porque preços não podem ser consultados."],"answer":2,"explanation":"Normalização respeita o significado do atributo e as dependências reais."},{"question":"Um total armazenado divergiu dos itens. O que deve ser a referência de reconstrução?","options":["O tema do dashboard.","O maior valor entre os dois sem investigar.","O número de índices.","Os fatos e a regra de cálculo documentada."],"answer":3,"explanation":"Resumos devem ter origem e regra verificáveis."}]},{"id":7,"title":"Escritas e ciclo de vida","tag":"Intermediário","hours":12,"summary":"Insira, altere e exclua dados com condições e efeitos verificáveis.","skills":["INSERT e conflito","UPDATE condicional","DELETE e inativação"],"project":"Operações de cadastro","deliverables":["Scripts de inclusão, alteração e inativação.","Registro dos efeitos esperados e observados.","Política de histórico para leitores e empréstimos."],"rubric":["Repetição de chave tem comportamento documentado.","Escritas preservam registros não alvo.","Exclusão considera dependências e retenção."],"challenge":[{"question":"A mesma chave idempotente chegou com outro valor. Qual comportamento precisa ser definido?","options":["Rejeitar ou explicar a divergência, em vez de tratá-la silenciosamente como repetição idêntica.","Somar o valor sem verificar.","Criar um índice em cada palavra.","Apagar a primeira requisição."],"answer":0,"explanation":"Idempotência depende da identidade e do significado da operação."},{"question":"Uma baixa condicional alterou zero linhas. A API pode anunciar sucesso sem checar?","options":["Sim, zero significa sempre sucesso.","Não; deve investigar ausência, conflito ou estoque insuficiente.","Sim, UPDATE nunca falha logicamente.","Não, porque todo UPDATE exige JOIN."],"answer":1,"explanation":"A escrita precisa confirmar o efeito esperado."},{"question":"Apagar um leitor com milhares de filhos em CASCADE é apenas uma alteração de uma linha?","options":["Sim, FKs não têm efeito na exclusão.","Sim, CASCADE só muda a ordem.","Não; pode remover toda a cadeia de registros dependentes.","Não, porque DELETE nunca aceita WHERE."],"answer":2,"explanation":"O impacto segue as relações declaradas."}]},{"id":8,"title":"SQL para análise","tag":"Avançado","hours":12,"summary":"Decomponha consultas e acrescente medidas sem perder a granularidade.","skills":["Subconsultas","CTEs","Janelas"],"project":"Painel de circulação","deliverables":["Consulta com CTE por leitor.","Ranking e acumulado com ordem definida.","Comparação de resultados com dados de empate."],"rubric":["Conjuntos de referência estão documentados.","CTEs têm nomes coerentes com sua granularidade.","Janelas usam frame e desempate apropriados."],"challenge":[{"question":"Uma pergunta exige todos os itens empatados em primeiro. LIMIT 1 é suficiente?","options":["Sim, LIMIT expande empates automaticamente.","Sim, qualquer máximo é único.","Não, porque ORDER BY é proibido.","Não, ele retorna somente uma linha."],"answer":3,"explanation":"O requisito de empate precisa fazer parte da consulta."},{"question":"Uma CTE se chama vendas_do_dia mas agrupa por cliente. Que melhoria de manutenção ajuda?","options":["Nomeá-la pela granularidade e documentar o filtro temporal.","Adicionar DISTINCT a toda coluna.","Remover os testes.","Afirmar que WITH sempre acelera."],"answer":0,"explanation":"Nomes precisam representar o conjunto produzido."},{"question":"GROUP BY e OVER são intercambiáveis quando precisamos de todas as linhas originais?","options":["Sim, ambos sempre retornam uma linha.","Não; GROUP BY reduz grupos, enquanto a janela pode preservar detalhes.","Sim, OVER apaga duplicações.","Não, porque SUM não aceita OVER."],"answer":1,"explanation":"A granularidade pretendida determina a ferramenta."}]},{"id":9,"title":"Transações e concorrência","tag":"Avançado","hours":12,"summary":"Preserve invariantes sob falhas e operações concorrentes.","skills":["ACID","Savepoints","Versão e idempotência"],"project":"Empréstimo transacional","deliverables":["Operação que registra empréstimo e baixa disponibilidade.","Teste de rollback entre as duas etapas.","Estratégia de repetição e conflito documentada."],"rubric":["Nunca confirma apenas metade da operação.","Zero linhas alteradas é tratado explicitamente.","Repetição da mesma operação não duplica efeitos."],"challenge":[{"question":"COMMIT após um UPDATE que não encontrou o destinatário garante transferência correta?","options":["Sim, COMMIT inventa o destinatário.","Sim, transação prova qualquer regra.","Não; o cliente precisa verificar os efeitos e as regras.","Não, porque COMMIT sempre desfaz."],"answer":2,"explanation":"A atomicidade não substitui a validação do domínio."},{"question":"RELEASE de um savepoint interno numa transação BEGIN confirma definitivamente tudo?","options":["Sim, sempre é igual a COMMIT externo.","Sim, mas só para texto.","Não, porque RELEASE apaga as tabelas.","Não; a transação externa ainda pode ser desfeita."],"answer":3,"explanation":"Os escopos de savepoint e transação precisam ser distinguidos."},{"question":"Após timeout de commit, repetir débito sem identificar a operação é seguro?","options":["Não; o primeiro débito pode já ter sido confirmado.","Sim, timeout sempre desfaz.","Sim, UPDATE só executa uma vez por usuário.","Não, porque bancos nunca permitem retries."],"answer":0,"explanation":"Resultado incerto exige identidade da operação e tratamento de repetição."}]},{"id":10,"title":"Desempenho com evidências","tag":"Avançado","hours":12,"summary":"Escolha índices, interprete planos e produza paginação coerente.","skills":["Índices","EXPLAIN","Paginação por chave"],"project":"Investigação de consulta","deliverables":["Consulta antes/depois com resultado conferido.","Plano e justificativa do índice escolhido.","Página por cursor com teste de empate."],"rubric":["Não confunde plano com tempo garantido.","Índices correspondem aos filtros reais.","O cursor preserva os componentes da ordem."],"challenge":[{"question":"Um índice (leitor_id,aberto) garante otimização idêntica para filtro só em aberto?","options":["Sim, a ordem das colunas nunca importa.","Não; a posição inicial e o plano precisam ser avaliados.","Sim, qualquer índice serve a qualquer filtro.","Não, porque índices só aceitam uma coluna."],"answer":1,"explanation":"A estrutura composta tem ordem e seletividade próprias."},{"question":"Dois planos diferentes retornam a mesma resposta correta. Um está necessariamente errado?","options":["Sim, SQL só permite um plano.","Sim, o mais longo está sempre errado.","Não; estratégias diferentes podem implementar a mesma consulta.","Não, porque nenhum plano executa SQL."],"answer":2,"explanation":"A avaliação separa semântica e custo."},{"question":"Um cursor só com data basta se várias linhas compartilham a mesma data?","options":["Sim, datas nunca repetem.","Sim, LIMIT resolve a identidade.","Não, porque cursores exigem texto.","Não; falta desempate estável, como data e id."],"answer":3,"explanation":"O cursor deve representar toda a ordem relevante."}]},{"id":11,"title":"Integração e evolução","tag":"Especialista","hours":12,"summary":"Conecte uma aplicação, evolua o esquema e teste os invariantes.","skills":["Binding de valores","Migrações","Fixtures"],"project":"Cliente seguro da biblioteca","deliverables":["Consulta parametrizada em Python.","Migração versionada com dados anteriores.","Casos positivos e negativos de integridade."],"rubric":["Entradas não são concatenadas na consulta.","Migração preserva dados e identifica a versão.","Testes verificam efeitos e estado, além da ausência de erro."],"challenge":[{"question":"SELECT ? FROM leitor com parâmetro nome seleciona a coluna nome?","options":["Não; seleciona o valor textual fornecido em cada linha.","Sim, placeholders substituem qualquer sintaxe.","Sim, desde que haja índice.","Não, porque parâmetros não aceitam texto."],"answer":0,"explanation":"Binding representa valores; identificadores exigem escolhas controladas."},{"question":"DDL transacional no SQLite garante rollback de DDL no MySQL e Oracle?","options":["Sim, todo SQL possui a mesma semântica.","Não; o comportamento precisa ser conferido por motor.","Sim, basta usar ponto e vírgula.","Não, porque SQLite não tem ALTER TABLE."],"answer":1,"explanation":"Dialetos e mecanismos transacionais não são uniformes."},{"question":"Por que uma fixture com apenas um filho por pai pode esconder erro de agregação?","options":["Porque um registro nunca pode ser consultado.","Porque COUNT exige dez registros.","Ela não exercita a multiplicação de linhas da relação 1:N.","Porque testes não aceitam FKs."],"answer":2,"explanation":"Os dados de teste precisam separar a implementação correta da falha possível."}]},{"id":12,"title":"Recuperação e projeto completo","tag":"Especialista","hours":12,"summary":"Escolha tecnologias conscientemente e entregue um laboratório recuperável.","skills":["Backup e RPO/RTO","Modelos e cargas","Revisão integrada"],"project":"Biblioteca com recuperação demonstrada","deliverables":["Schema, fixtures e consultas da biblioteca.","Cliente parametrizado e fluxo transacional testado.","Backup em arquivo, restauração separada e relatório de decisões."],"rubric":["Banco novo reproduz todos os resultados documentados.","Invariantes rejeitam empréstimo duplo e referências órfãs.","Restauração é aberta e verificada; limites são explicitados."],"challenge":[{"question":"Gerar arquivo de backup sem abrir uma restauração prova recuperabilidade?","options":["Sim, o nome do arquivo basta.","Sim, se o arquivo tiver extensão db.","Não, porque backup não pode ser arquivo.","Não; é necessário testar a leitura e as regras no destino recuperado."],"answer":3,"explanation":"A evidência está no processo de recuperação, não só na criação da cópia."},{"question":"O banco mais citado numa pesquisa é sempre a melhor escolha para qualquer projeto?","options":["Não; a carga e os requisitos precisam orientar a decisão.","Sim, ranking elimina análise técnica.","Sim, popularidade mede qualquer latência.","Não, porque pesquisas não podem mencionar SQL."],"answer":0,"explanation":"A seleção combina necessidades concretas com evidências do ecossistema."},{"question":"Depois de devolver um exemplar, o histórico antigo precisa ser apagado para emprestá-lo de novo?","options":["Sim, índices sempre proíbem histórico.","Não; a unicidade parcial controla somente os empréstimos ainda abertos.","Sim, FK exige uma única linha para sempre.","Não, porque a data de devolução vira chave primária."],"answer":1,"explanation":"O predicado diferencia estado atual de histórico."}]}],"lessons":[{"id":1,"level":1,"title":"Dados, informações e consultas","goal":"Distinguir dado armazenado, consulta e interpretação de negócio.","theory":[{"title":"Uma pergunta de cada vez","text":"Um dado isolado, como 1200, precisa de contexto: são centavos, pessoas ou segundos? Nomeie unidade e significado antes de armazenar. Um banco organiza fatos para responder perguntas reproduzíveis."},{"title":"O papel do SGBD","text":"O sistema gerenciador interpreta comandos, verifica regras e coordena acesso. SQL descreve o resultado desejado; o motor decide como obtê-lo. O cliente de terminal envia instruções ao motor."},{"title":"Primeiro resultado","text":"SELECT também calcula expressões sem tabela. AS nomeia uma coluna do resultado; não cria um campo persistente. O ponto e vírgula encerra a instrução."}],"code":"SELECT 1200 AS preco_centavos, 3 AS quantidade, 1200 * 3 AS total_centavos;\n","filename":"aula.sql","language":"sql","run":"Abra uma sessão nova em memória: sqlite3 :memory:\nNo prompt, use .headers off e .mode list; depois .read aula.sql\nCada exemplo contém sua própria preparação e não depende da aula anterior.","expected":"1200|3|3600","quiz":{"question":"O alias total_centavos cria uma coluna persistente?","options":["Sim, em qualquer tabela.","Não; ele nomeia a expressão no resultado.","Sim, mas somente após reiniciar.","Não, porque SELECT nunca calcula valores."],"answer":1,"explanation":"Alias descreve o resultado da consulta; persistência depende de uma tabela e de escrita."},"exercises":[{"id":1,"title":"Calcule o valor de quatro livros de 1550 centavos","prompt":"Calcule o valor de quatro livros de 1550 centavos.","hint":"Troque os operandos da multiplicação.","solution":"SELECT 1550 * 4 AS total_centavos; produz 6200.","criteria":["A consulta retorna 6200 e explicita a unidade.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":2,"title":"Explique a diferença entre sqlite3 e SELECT","prompt":"Explique a diferença entre sqlite3 e SELECT.","hint":"Um é ferramenta; o outro pertence à linguagem.","solution":"sqlite3 é o programa cliente e motor embutido; SELECT é uma instrução SQL que ele interpreta.","criteria":["Identifica cliente, motor e instrução.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":3,"title":"Represente desconto de 300 centavos sobre 2400","prompt":"Represente desconto de 300 centavos sobre 2400.","hint":"Operações inteiras evitam ambiguidade monetária aqui.","solution":"SELECT 2400 - 300 AS total_centavos; retorna 2100.","criteria":["Retorna 2100 sem usar texto como preço.","Registre o resultado e explique qual regra do banco o produziu."]}],"source":"https://www.sqlite.org/lang_select.html","caution":"Laboratório em SQLite; verifique o dialeto ao migrar para outro SGBD. O editor salva o arquivo, mas a execução é local.","local":true,"hours":4,"minutes":45},{"id":2,"level":1,"title":"Tabelas, linhas e colunas","goal":"Criar uma relação simples e consultar suas linhas.","theory":[{"title":"Uma linha representa um fato","text":"Nesta tabela cada linha representa um livro. Colunas descrevem atributos do mesmo tipo de entidade. Guardar vários títulos separados por vírgula em um campo dificulta busca e integridade."},{"title":"Esquema e dados","text":"CREATE TABLE define a estrutura. INSERT adiciona fatos. SELECT consulta. Mudar dados não é a mesma operação que alterar o esquema. Declarar colunas no INSERT evita depender de sua ordem física."},{"title":"Ordem explícita","text":"Uma tabela não tem ordem de apresentação garantida. ORDER BY é necessário quando a ordem faz parte do resultado esperado, inclusive em testes."}],"code":"CREATE TABLE livro(id INTEGER, titulo TEXT);\nINSERT INTO livro(id,titulo) VALUES(2,'Redes'),(1,'Algoritmos');\nSELECT id,titulo FROM livro ORDER BY id;\n","filename":"aula.sql","language":"sql","run":"Abra uma sessão nova em memória: sqlite3 :memory:\nNo prompt, use .headers off e .mode list; depois .read aula.sql\nCada exemplo contém sua própria preparação e não depende da aula anterior.","expected":"1|Algoritmos\n2|Redes","quiz":{"question":"O que cada linha da tabela livro representa neste modelo?","options":["Uma coluna.","Um comando SQL.","Um livro identificado por seus atributos.","Um banco inteiro."],"answer":2,"explanation":"Definir a granularidade da linha evita misturar fatos diferentes."},"exercises":[{"id":1,"title":"Cadastre o livro 3, Banco de Dados","prompt":"Cadastre o livro 3, Banco de Dados.","hint":"Use os mesmos nomes de colunas.","solution":"INSERT INTO livro(id,titulo) VALUES(3,'Banco de Dados');","criteria":["A consulta ordenada tem três linhas.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":2,"title":"Mostre apenas os títulos em ordem alfabética","prompt":"Mostre apenas os títulos em ordem alfabética.","hint":"Projeção escolhe colunas e ORDER BY escolhe ordem.","solution":"SELECT titulo FROM livro ORDER BY titulo;","criteria":["Retorna somente uma coluna e tem ORDER BY.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":3,"title":"Compare duas linhas com o mesmo id","prompt":"Compare duas linhas com o mesmo id.","hint":"Ainda não declaramos unicidade.","solution":"O esquema atual aceita IDs repetidos. Uma chave primária será necessária para proibir essa ambiguidade.","criteria":["Demonstra a duplicação e identifica a regra ausente.","Registre o resultado e explique qual regra do banco o produziu."]}],"source":"https://www.sqlite.org/lang_createtable.html","caution":"Laboratório em SQLite; verifique o dialeto ao migrar para outro SGBD. O editor salva o arquivo, mas a execução é local.","local":true,"hours":4,"minutes":45},{"id":3,"level":1,"title":"Domínios e regras de integridade","goal":"Declarar valores obrigatórios e limites do domínio.","theory":[{"title":"Domínio de um atributo","text":"Escolha o significado antes do tipo. Quantidade precisa de unidade e intervalo; nome pode ser obrigatório. Valores monetários em centavos inteiros simplificam estes exercícios, sem ser regra universal para todo domínio."},{"title":"Regras no banco","text":"NOT NULL impede ausência, CHECK valida uma expressão e UNIQUE controla duplicações. Validação de interface melhora a experiência, mas o banco também protege escritas de outras aplicações."},{"title":"NULL exige atenção","text":"CHECK considera falha quando a expressão é falsa; ausência pode exigir NOT NULL separado. No SQLite tipos usuais têm afinidade; esta base não pressupõe rigidez idêntica à de outros motores."}],"code":"CREATE TABLE item(id INTEGER PRIMARY KEY, nome TEXT NOT NULL, estoque INTEGER NOT NULL CHECK(estoque>=0));\nINSERT INTO item VALUES(1,'Caderno',4);\nSELECT nome,estoque FROM item;\n","filename":"aula.sql","language":"sql","run":"Abra uma sessão nova em memória: sqlite3 :memory:\nNo prompt, use .headers off e .mode list; depois .read aula.sql\nCada exemplo contém sua própria preparação e não depende da aula anterior.","expected":"Caderno|4","quiz":{"question":"Qual regra proíbe estoque negativo e também ausência de estoque?","options":["Apenas ORDER BY.","Apenas nomear a coluna estoque.","Apenas usar SELECT DISTINCT.","NOT NULL combinado com CHECK(estoque>=0)."],"answer":3,"explanation":"A obrigatoriedade e o intervalo são restrições diferentes."},"exercises":[{"id":1,"title":"Tente cadastrar estoque -1 e descreva a falha","prompt":"Tente cadastrar estoque -1 e descreva a falha.","hint":"Execute a tentativa separadamente para observar o erro.","solution":"INSERT INTO item VALUES(2,'Caneta',-1); falha por CHECK e não insere a linha.","criteria":["Identifica a restrição violada e confirma que há só uma linha.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":2,"title":"Imponha nome único em uma tabela nova","prompt":"Imponha nome único em uma tabela nova.","hint":"UNIQUE é uma regra de esquema.","solution":"CREATE TABLE categoria(id INTEGER PRIMARY KEY,nome TEXT NOT NULL UNIQUE);","criteria":["Segundo nome idêntico é rejeitado.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":3,"title":"Explique por que validação só na tela é insuficiente","prompt":"Explique por que validação só na tela é insuficiente.","hint":"Considere dois clientes escrevendo no mesmo banco.","solution":"Outro programa ou importação pode ignorar a tela; constraints aplicam a regra a qualquer escrita.","criteria":["Inclui uma via de escrita que não usa a interface.","Registre o resultado e explique qual regra do banco o produziu."]}],"source":"https://www.sqlite.org/lang_createtable.html","caution":"Laboratório em SQLite; verifique o dialeto ao migrar para outro SGBD. O editor salva o arquivo, mas a execução é local.","local":true,"hours":4,"minutes":45},{"id":4,"level":2,"title":"Chaves e identidade","goal":"Escolher identificadores estáveis e distinguir chaves candidatas.","theory":[{"title":"Identidade estável","text":"O nome de uma pessoa pode mudar ou repetir. Uma chave identifica a linha independentemente dos atributos descritivos. Uma chave candidata é um conjunto mínimo de atributos que identifica unicamente; uma delas é escolhida como primária."},{"title":"Chave natural e substituta","text":"Um código de negócio pode ser uma chave natural. Um ID gerado é substituto. Usar ID não elimina a necessidade de UNIQUE no identificador de negócio que também precisa ser único."},{"title":"Unicidade e ausência","text":"PRIMARY KEY expressa identidade. As regras de geração de IDs variam por motor; INTEGER PRIMARY KEY possui comportamento específico no SQLite. Aqui fornecemos IDs explicitamente para tornar o teste claro."}],"code":"CREATE TABLE leitor(id INTEGER PRIMARY KEY, email TEXT NOT NULL UNIQUE, nome TEXT NOT NULL);\nINSERT INTO leitor VALUES(1,'ana@example.test','Ana'),(2,'bia@example.test','Ana');\nSELECT id,nome FROM leitor ORDER BY id;\n","filename":"aula.sql","language":"sql","run":"Abra uma sessão nova em memória: sqlite3 :memory:\nNo prompt, use .headers off e .mode list; depois .read aula.sql\nCada exemplo contém sua própria preparação e não depende da aula anterior.","expected":"1|Ana\n2|Ana","quiz":{"question":"Por que nome não é uma boa chave neste exemplo?","options":["Pessoas diferentes podem ter o mesmo nome.","Porque TEXT nunca pode ter UNIQUE.","Porque nomes não podem mudar.","Porque SQL proíbe pesquisar texto."],"answer":0,"explanation":"A identidade não pode depender de um atributo que admite repetição no domínio."},"exercises":[{"id":1,"title":"Tente duplicar o e-mail com outro ID","prompt":"Tente duplicar o e-mail com outro ID.","hint":"O ID e o e-mail têm regras independentes.","solution":"INSERT INTO leitor VALUES(3,'ana@example.test','Outra'); falha por UNIQUE(email).","criteria":["Identifica a unicidade de negócio preservada.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":2,"title":"Atualize o nome de Ana sem trocar a chave","prompt":"Atualize o nome de Ana sem trocar a chave.","hint":"Use WHERE no ID.","solution":"UPDATE leitor SET nome='Ana Lima' WHERE id=1;","criteria":["Somente o registro 1 muda e continua com id 1.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":3,"title":"Proponha duas chaves candidatas para um cadastro com CPF obrigatório e matrícula única","prompt":"Proponha duas chaves candidatas para um cadastro com CPF obrigatório e matrícula única.","hint":"Candidata é mínima e depende das regras do domínio.","solution":"Se ambas forem obrigatórias e únicas, CPF e matrícula são candidatas separadas; escolha uma como primária e proteja a outra com UNIQUE.","criteria":["Explicita as hipóteses de obrigatoriedade e unicidade.","Registre o resultado e explique qual regra do banco o produziu."]}],"source":"https://www.sqlite.org/lang_createtable.html","caution":"Laboratório em SQLite; verifique o dialeto ao migrar para outro SGBD. O editor salva o arquivo, mas a execução é local.","local":true,"hours":4,"minutes":45},{"id":5,"level":2,"title":"Relacionamentos e chaves estrangeiras","goal":"Modelar uma relação de um para muitos com referência válida.","theory":[{"title":"Cardinalidade","text":"Um leitor pode ter muitos empréstimos, mas cada empréstimo deste modelo pertence a um leitor. A referência fica no lado muitos: emprestimo.leitor_id aponta para leitor.id."},{"title":"Integridade referencial","text":"FOREIGN KEY impede referências inexistentes quando a verificação está habilitada. No SQLite ative PRAGMA foreign_keys=ON em cada conexão, antes da transação; declarar a cláusula sem verificar o ambiente é insuficiente."},{"title":"Ciclo de vida","text":"ON DELETE determina o que fazer quando o pai é apagado. RESTRICT, CASCADE e SET NULL têm efeitos de domínio diferentes. Não apague históricos automaticamente só porque a sintaxe permite."}],"code":"PRAGMA foreign_keys=ON;\nCREATE TABLE leitor(id INTEGER PRIMARY KEY,nome TEXT NOT NULL);\nCREATE TABLE emprestimo(id INTEGER PRIMARY KEY,leitor_id INTEGER NOT NULL REFERENCES leitor(id));\nINSERT INTO leitor VALUES(1,'Ana');\nINSERT INTO emprestimo VALUES(10,1);\nSELECT e.id,l.nome FROM emprestimo e JOIN leitor l ON l.id=e.leitor_id;\n","filename":"aula.sql","language":"sql","run":"Abra uma sessão nova em memória: sqlite3 :memory:\nNo prompt, use .headers off e .mode list; depois .read aula.sql\nCada exemplo contém sua própria preparação e não depende da aula anterior.","expected":"10|Ana","quiz":{"question":"Onde fica a FK de leitor neste modelo 1:N?","options":["Somente em uma planilha externa.","Na tabela emprestimo, o lado muitos.","No título do livro.","Sempre nos dois lados como texto duplicado."],"answer":1,"explanation":"Vários empréstimos podem referenciar a mesma chave de leitor."},"exercises":[{"id":1,"title":"Tente emprestar para leitor 99","prompt":"Tente emprestar para leitor 99.","hint":"A tabela pai não contém esse ID.","solution":"INSERT INTO emprestimo VALUES(11,99); falha com foreign key habilitada.","criteria":["A referência órfã é rejeitada.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":2,"title":"Explique quando SET NULL é inadequado","prompt":"Explique quando SET NULL é inadequado.","hint":"Considere a obrigatoriedade do leitor no histórico.","solution":"É inadequado quando empréstimo sempre precisa de leitor; NOT NULL e preservação do pai refletem essa regra.","criteria":["Relaciona a ação à cardinalidade e ao histórico.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":3,"title":"Confira a habilitação da verificação no laboratório","prompt":"Confira a habilitação da verificação no laboratório.","hint":"O PRAGMA é por conexão.","solution":"PRAGMA foreign_keys; deve retornar 1 nesta sessão.","criteria":["Verifica 1 antes de testar a FK.","Registre o resultado e explique qual regra do banco o produziu."]}],"source":"https://www.sqlite.org/foreignkeys.html","caution":"Laboratório em SQLite; verifique o dialeto ao migrar para outro SGBD. O editor salva o arquivo, mas a execução é local.","local":true,"hours":4,"minutes":45},{"id":6,"level":2,"title":"Relações de muitos para muitos","goal":"Criar uma tabela associativa sem duplicações.","theory":[{"title":"Duas direções","text":"Um livro pode ter vários autores e um autor pode escrever vários livros. Uma lista dentro da coluna não protege a existência de cada autor. Modele a associação como uma tabela própria."},{"title":"Chave composta","text":"O par livro_id,autor_id identifica uma associação. A chave composta impede repetir o mesmo par e ainda permite cada ID em outras combinações. Ambos os componentes são obrigatórios."},{"title":"Atributos da relação","text":"Ordem de autoria pertence à associação, não somente ao autor ou ao livro. Perguntar a qual fato um atributo pertence orienta a decomposição."}],"code":"PRAGMA foreign_keys=ON;\nCREATE TABLE livro(id INTEGER PRIMARY KEY); CREATE TABLE autor(id INTEGER PRIMARY KEY);\nCREATE TABLE autoria(livro_id INTEGER NOT NULL REFERENCES livro(id), autor_id INTEGER NOT NULL REFERENCES autor(id),PRIMARY KEY(livro_id,autor_id));\nINSERT INTO livro VALUES(1); INSERT INTO autor VALUES(10),(20);\nINSERT INTO autoria VALUES(1,10),(1,20);\nSELECT livro_id,autor_id FROM autoria ORDER BY autor_id;\n","filename":"aula.sql","language":"sql","run":"Abra uma sessão nova em memória: sqlite3 :memory:\nNo prompt, use .headers off e .mode list; depois .read aula.sql\nCada exemplo contém sua própria preparação e não depende da aula anterior.","expected":"1|10\n1|20","quiz":{"question":"Qual chave impede repetir o mesmo autor no mesmo livro?","options":["PRIMARY KEY apenas em autor_id.","Um campo com nomes separados por vírgula.","PRIMARY KEY(livro_id,autor_id).","ORDER BY nos dois campos."],"answer":2,"explanation":"O par representa a identidade da associação."},"exercises":[{"id":1,"title":"Teste inserir o par (1,10) novamente","prompt":"Teste inserir o par (1,10) novamente.","hint":"Compare associação repetida com autor em outro livro.","solution":"INSERT INTO autoria VALUES(1,10); falha por chave composta.","criteria":["O par duplicado é rejeitado.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":2,"title":"Acrescente ordem_autoria ao modelo","prompt":"Acrescente ordem_autoria ao modelo.","hint":"Esse dado varia por livro e autor.","solution":"Declare ordem_autoria INTEGER NOT NULL CHECK(ordem_autoria>0) na tabela autoria; se a regra exigir, UNIQUE(livro_id,ordem_autoria).","criteria":["A ordem pertence à associação e tem limite positivo.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":3,"title":"Desenhe livro, autor e autoria com suas FKs","prompt":"Desenhe livro, autor e autoria com suas FKs.","hint":"São duas relações 1:N por intermédio da associação.","solution":"livro 1:N autoria e autor 1:N autoria; autoria aponta para as duas chaves pais.","criteria":["As duas FKs e as cardinalidades estão identificadas.","Registre o resultado e explique qual regra do banco o produziu."]}],"source":"https://www.sqlite.org/foreignkeys.html","caution":"Laboratório em SQLite; verifique o dialeto ao migrar para outro SGBD. O editor salva o arquivo, mas a execução é local.","local":true,"hours":4,"minutes":45},{"id":7,"level":3,"title":"Filtros e lógica booleana","goal":"Traduzir condições de negócio para WHERE com precedência clara.","theory":[{"title":"Selecionar linhas","text":"WHERE mantém linhas para as quais a condição é verdadeira. Escreva a regra em linguagem natural antes do SQL e teste valores na fronteira: menor, igual e maior que o limite."},{"title":"Combinar condições","text":"AND exige as duas condições; OR permite qualquer uma. Parênteses deixam a intenção explícita quando a regra mistura operadores. BETWEEN inclui os dois extremos."},{"title":"Teste de fronteira","text":"Dois filtros que parecem equivalentes podem diferir em igualdade ou precedência. Use dados pequenos, com casos que deveriam entrar e outros que deveriam ficar fora."}],"code":"CREATE TABLE item(id INTEGER PRIMARY KEY,preco INTEGER,ativo INTEGER);\nINSERT INTO item VALUES(1,1000,1),(2,2000,1),(3,900,0);\nSELECT id FROM item WHERE ativo=1 AND preco<=1000 ORDER BY id;\n","filename":"aula.sql","language":"sql","run":"Abra uma sessão nova em memória: sqlite3 :memory:\nNo prompt, use .headers off e .mode list; depois .read aula.sql\nCada exemplo contém sua própria preparação e não depende da aula anterior.","expected":"1","quiz":{"question":"preco<=1000 inclui preço exatamente 1000?","options":["Não, somente abaixo de 1000.","Só se houver GROUP BY.","Somente se o preço for texto.","Sim, a igualdade faz parte do operador."],"answer":3,"explanation":"Testes de fronteira tornam o requisito observável."},"exercises":[{"id":1,"title":"Filtre ativos com preço de 1000 a 2000 inclusive","prompt":"Filtre ativos com preço de 1000 a 2000 inclusive.","hint":"BETWEEN inclui os limites.","solution":"SELECT id FROM item WHERE ativo=1 AND preco BETWEEN 1000 AND 2000 ORDER BY id; retorna 1 e 2.","criteria":["Retorna 1 e 2, sem incluir inativos.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":2,"title":"Compare (ativo=1 AND preco<1000) OR id=3 com ativo=1 AND (preco<1000 OR id=3)","prompt":"Compare (ativo=1 AND preco<1000) OR id=3 com ativo=1 AND (preco<1000 OR id=3).","hint":"O item 3 diferencia as expressões.","solution":"A primeira inclui o item 3; a segunda não, pois exige ativo=1 para todos os casos.","criteria":["Explica a diferença usando o registro 3.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":3,"title":"Crie casos em 999,1000,1001 para limite <=1000","prompt":"Crie casos em 999,1000,1001 para limite <=1000.","hint":"Teste antes, na fronteira e depois.","solution":"999 e 1000 entram; 1001 fica fora. Registre a tabela de decisão antes de executar.","criteria":["Os três casos possuem resultado previsto.","Registre o resultado e explique qual regra do banco o produziu."]}],"source":"https://www.sqlite.org/lang_expr.html","caution":"Laboratório em SQLite; verifique o dialeto ao migrar para outro SGBD. O editor salva o arquivo, mas a execução é local.","local":true,"hours":4,"minutes":45},{"id":8,"level":3,"title":"NULL e valores ausentes","goal":"Consultar ausência sem confundi-la com zero ou texto vazio.","theory":[{"title":"Ausência tem significado","text":"NULL representa ausência ou desconhecimento conforme o modelo. Zero é um valor conhecido. Defina se uma data ausente indica empréstimo aberto, dado desconhecido ou cadastro incompleto."},{"title":"Três resultados lógicos","text":"Comparar um valor com NULL usando = não produz verdadeiro. Use IS NULL ou IS NOT NULL. WHERE só conserva verdadeiro, descartando também o resultado desconhecido."},{"title":"Apresentação e armazenamento","text":"COALESCE escolhe o primeiro valor não nulo. Ele ajuda a exibir um padrão, mas não altera a informação armazenada nem resolve uma regra de domínio mal definida."}],"code":"CREATE TABLE emprestimo(id INTEGER PRIMARY KEY,devolvido_em TEXT);\nINSERT INTO emprestimo VALUES(1,NULL),(2,'2026-01-10');\nSELECT id,COALESCE(devolvido_em,'aberto') FROM emprestimo WHERE devolvido_em IS NULL;\n","filename":"aula.sql","language":"sql","run":"Abra uma sessão nova em memória: sqlite3 :memory:\nNo prompt, use .headers off e .mode list; depois .read aula.sql\nCada exemplo contém sua própria preparação e não depende da aula anterior.","expected":"1|aberto","quiz":{"question":"Qual predicado encontra empréstimos sem data de devolução?","options":["devolvido_em IS NULL.","devolvido_em = NULL.","devolvido_em = 0.","devolvido_em = 'NULL'."],"answer":0,"explanation":"NULL é um marcador de ausência, não a string NULL ou o número zero."},"exercises":[{"id":1,"title":"Consulte somente empréstimos devolvidos","prompt":"Consulte somente empréstimos devolvidos.","hint":"Inverta o teste de ausência.","solution":"SELECT id FROM emprestimo WHERE devolvido_em IS NOT NULL; retorna 2.","criteria":["Retorna apenas o ID 2.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":2,"title":"Explique por que = NULL não encontra a linha 1","prompt":"Explique por que = NULL não encontra a linha 1.","hint":"WHERE conserva somente verdadeiro.","solution":"A comparação produz desconhecido, portanto não passa no filtro; IS NULL testa a ausência.","criteria":["Distingue desconhecido de verdadeiro.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":3,"title":"Mostre todos os empréstimos com rótulo de aberto","prompt":"Mostre todos os empréstimos com rótulo de aberto.","hint":"Use COALESCE na projeção, sem filtrar.","solution":"SELECT id,COALESCE(devolvido_em,'aberto') FROM emprestimo ORDER BY id;","criteria":["A linha 1 mostra aberto e a linha 2 conserva a data.","Registre o resultado e explique qual regra do banco o produziu."]}],"source":"https://www.sqlite.org/lang_expr.html","caution":"Laboratório em SQLite; verifique o dialeto ao migrar para outro SGBD. O editor salva o arquivo, mas a execução é local.","local":true,"hours":4,"minutes":45},{"id":9,"level":3,"title":"Ordenação e paginação inicial","goal":"Produzir resultados limitados com desempate determinístico.","theory":[{"title":"Ordenar não filtra","text":"ORDER BY organiza a apresentação. ASC é crescente e DESC é decrescente. Escolha um desempate estável para resultados repetíveis."},{"title":"Limitar resultados","text":"LIMIT e OFFSET são a sintaxe de paginação do laboratório; outros dialetos podem usar FETCH ou TOP. Sem ordem explícita, primeiros registros não possuem significado estável."},{"title":"Página sob mudanças","text":"OFFSET pula uma quantidade de linhas. Inserções entre requisições podem deslocar páginas. Essa abordagem é útil para começar, mas a paginação por chave será vista depois."}],"code":"CREATE TABLE livro(id INTEGER PRIMARY KEY,titulo TEXT);\nINSERT INTO livro VALUES(1,'Go'),(2,'SQL'),(3,'SQL'),(4,'Web');\nSELECT id,titulo FROM livro ORDER BY titulo,id LIMIT 2 OFFSET 1;\n","filename":"aula.sql","language":"sql","run":"Abra uma sessão nova em memória: sqlite3 :memory:\nNo prompt, use .headers off e .mode list; depois .read aula.sql\nCada exemplo contém sua própria preparação e não depende da aula anterior.","expected":"2|SQL\n3|SQL","quiz":{"question":"Por que ordenar por titulo,id em vez de só titulo?","options":["Porque id converte tudo em texto.","id desempata títulos iguais.","Porque LIMIT exige exatamente duas colunas.","Porque ORDER BY cria uma chave estrangeira."],"answer":1,"explanation":"Um desempate único torna a sequência bem definida."},"exercises":[{"id":1,"title":"Mostre a primeira página de dois livros","prompt":"Mostre a primeira página de dois livros.","hint":"A primeira página pula zero linhas.","solution":"SELECT id,titulo FROM livro ORDER BY titulo,id LIMIT 2 OFFSET 0;","criteria":["Retorna IDs 1 e 2 nessa ordem.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":2,"title":"Mostre os dois maiores IDs","prompt":"Mostre os dois maiores IDs.","hint":"Ordene antes de limitar.","solution":"SELECT id FROM livro ORDER BY id DESC LIMIT 2; retorna 4 e 3.","criteria":["A ordem é decrescente e há duas linhas.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":3,"title":"Explique um problema ao inserir um título antes da segunda página","prompt":"Explique um problema ao inserir um título antes da segunda página.","hint":"Considere como o deslocamento numérico muda.","solution":"A linha inserida pode empurrar um registro já visto para a página seguinte, causando repetição; cursor por chave é uma alternativa.","criteria":["Apresenta um exemplo concreto de deslocamento.","Registre o resultado e explique qual regra do banco o produziu."]}],"source":"https://www.sqlite.org/lang_select.html","caution":"Laboratório em SQLite; verifique o dialeto ao migrar para outro SGBD. O editor salva o arquivo, mas a execução é local.","local":true,"hours":4,"minutes":45},{"id":10,"level":4,"title":"Agregação e granularidade","goal":"Contar fatos na unidade correta e distinguir COUNT(*) de COUNT(coluna).","theory":[{"title":"Mudar a granularidade","text":"Uma agregação reduz várias linhas a uma medida. Antes de escrever SUM ou COUNT, declare se você conta vendas, itens ou pessoas. Misturar granularidades produz relatórios aparentemente válidos e numericamente errados."},{"title":"Grupos","text":"GROUP BY forma grupos pelas expressões escolhidas. Projete atributos agrupados e medidas agregadas; não dependa da tolerância de um dialeto para escolher colunas sem significado definido."},{"title":"Ausência na medida","text":"COUNT(*) conta linhas; COUNT(coluna) conta valores não nulos. SUM e AVG também tratam ausência de modo distinto de zero. Defina o denominador do indicador."}],"code":"CREATE TABLE venda(id INTEGER PRIMARY KEY,categoria TEXT,valor INTEGER);\nINSERT INTO venda VALUES(1,'livro',1000),(2,'livro',2000),(3,'jogo',NULL);\nSELECT categoria,COUNT(*),COUNT(valor),SUM(valor) FROM venda GROUP BY categoria ORDER BY categoria;\n","filename":"aula.sql","language":"sql","run":"Abra uma sessão nova em memória: sqlite3 :memory:\nNo prompt, use .headers off e .mode list; depois .read aula.sql\nCada exemplo contém sua própria preparação e não depende da aula anterior.","expected":"jogo|1|0|\nlivro|2|2|3000","quiz":{"question":"COUNT(valor) conta a venda cujo valor é NULL?","options":["Sim, como zero.","Sim, como um.","Não, ele conta apenas valores não nulos.","Só quando há índice."],"answer":2,"explanation":"COUNT(*) e COUNT(valor) respondem perguntas diferentes."},"exercises":[{"id":1,"title":"Calcule a soma conhecida da categoria livro","prompt":"Calcule a soma conhecida da categoria livro.","hint":"Filtre antes de agregar.","solution":"SELECT SUM(valor) FROM venda WHERE categoria='livro'; retorna 3000.","criteria":["Retorna 3000 centavos.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":2,"title":"Conte categorias distintas com valor conhecido","prompt":"Conte categorias distintas com valor conhecido.","hint":"DISTINCT remove repetições dentro de COUNT.","solution":"SELECT COUNT(DISTINCT categoria) FROM venda WHERE valor IS NOT NULL; retorna 1.","criteria":["O critério de valor conhecido está explícito.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":3,"title":"Explique por que ausência não deve virar zero silenciosamente no ticket médio","prompt":"Explique por que ausência não deve virar zero silenciosamente no ticket médio.","hint":"O denominador muda.","solution":"AVG ignora NULL; usar COALESCE(valor,0) inclui a venda sem valor como zero. É preciso decidir a regra do indicador.","criteria":["Identifica a mudança de denominador.","Registre o resultado e explique qual regra do banco o produziu."]}],"source":"https://www.sqlite.org/lang_aggfunc.html","caution":"Laboratório em SQLite; verifique o dialeto ao migrar para outro SGBD. O editor salva o arquivo, mas a execução é local.","local":true,"hours":4,"minutes":45},{"id":11,"level":4,"title":"WHERE e HAVING","goal":"Separar o filtro de linhas do filtro de grupos.","theory":[{"title":"Antes da agregação","text":"WHERE filtra as linhas de entrada. Excluir cancelamentos antes de somar é diferente de somar tudo e tentar retirar o efeito depois."},{"title":"Depois da agregação","text":"HAVING filtra os grupos com base em medidas como SUM ou COUNT. Uma condição SUM(valor)>1000 pertence a essa etapa lógica."},{"title":"Leitura da consulta","text":"Leia FROM, WHERE, GROUP BY, HAVING e SELECT como etapas conceituais. Isso ajuda a explicar o resultado sem supor uma ordem física específica de execução do motor."}],"code":"CREATE TABLE venda(categoria TEXT,valor INTEGER,cancelada INTEGER);\nINSERT INTO venda VALUES('livro',1000,0),('livro',900,0),('jogo',5000,1),('jogo',500,0);\nSELECT categoria,SUM(valor) FROM venda WHERE cancelada=0 GROUP BY categoria HAVING SUM(valor)>1000 ORDER BY categoria;\n","filename":"aula.sql","language":"sql","run":"Abra uma sessão nova em memória: sqlite3 :memory:\nNo prompt, use .headers off e .mode list; depois .read aula.sql\nCada exemplo contém sua própria preparação e não depende da aula anterior.","expected":"livro|1900","quiz":{"question":"Qual cláusula filtra grupos cuja soma passa de 1000?","options":["WHERE SUM(valor)>1000.","ORDER BY SUM(valor)>1000.","LIMIT SUM(valor)>1000.","HAVING SUM(valor)>1000."],"answer":3,"explanation":"HAVING observa o resultado agregado de cada grupo."},"exercises":[{"id":1,"title":"Liste categorias com pelo menos duas vendas não canceladas","prompt":"Liste categorias com pelo menos duas vendas não canceladas.","hint":"COUNT ocorre depois de WHERE.","solution":"SELECT categoria FROM venda WHERE cancelada=0 GROUP BY categoria HAVING COUNT(*)>=2; retorna livro.","criteria":["Usa WHERE para cancelamento e HAVING para contagem.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":2,"title":"Retire o WHERE e explique a mudança","prompt":"Retire o WHERE e explique a mudança.","hint":"A venda cancelada tem valor alto.","solution":"jogo também passa de 1000 porque a soma inclui os 5000 cancelados.","criteria":["Explica por que jogo passa a entrar.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":3,"title":"Inclua grupos com soma exatamente 1000","prompt":"Inclua grupos com soma exatamente 1000.","hint":"Revise o operador de fronteira.","solution":"Troque > por >= em HAVING; registre um grupo de teste cuja soma seja 1000.","criteria":["O caso de igualdade está testado.","Registre o resultado e explique qual regra do banco o produziu."]}],"source":"https://www.sqlite.org/lang_select.html","caution":"Laboratório em SQLite; verifique o dialeto ao migrar para outro SGBD. O editor salva o arquivo, mas a execução é local.","local":true,"hours":4,"minutes":45},{"id":12,"level":4,"title":"CASE e indicadores condicionais","goal":"Construir classificações e contagens condicionais legíveis.","theory":[{"title":"Classificação","text":"CASE retorna uma expressão conforme a primeira condição verdadeira. Condições sobrepostas exigem ordem intencional. ELSE documenta o comportamento dos demais casos."},{"title":"Medidas condicionais","text":"SUM(CASE WHEN ... THEN 1 ELSE 0 END) conta linhas que atendem a uma condição. Isso permite comparar indicadores na mesma granularidade."},{"title":"Limites de negócio","text":"Uma faixa como atrasado deve ter referência temporal definida. Nesta aula usamos dias inteiros para isolar a lógica; produção exigirá datas, fuso e uma regra de corte clara."}],"code":"CREATE TABLE entrega(id INTEGER PRIMARY KEY,dias INTEGER);\nINSERT INTO entrega VALUES(1,0),(2,3),(3,10);\nSELECT SUM(CASE WHEN dias>5 THEN 1 ELSE 0 END),COUNT(*) FROM entrega;\n","filename":"aula.sql","language":"sql","run":"Abra uma sessão nova em memória: sqlite3 :memory:\nNo prompt, use .headers off e .mode list; depois .read aula.sql\nCada exemplo contém sua própria preparação e não depende da aula anterior.","expected":"1|3","quiz":{"question":"Que valor o CASE deve produzir para uma linha que não atende à condição nessa contagem?","options":["Zero, para não acrescentar à soma.","NULL obrigatoriamente em qualquer contagem.","O ID de outra tabela.","A palavra SUM."],"answer":0,"explanation":"Somar 1 para verdadeiro e 0 para falso torna a contagem explícita."},"exercises":[{"id":1,"title":"Conte entregas com dias=0","prompt":"Conte entregas com dias=0.","hint":"Mude somente o predicado do CASE.","solution":"SELECT SUM(CASE WHEN dias=0 THEN 1 ELSE 0 END) FROM entrega; retorna 1.","criteria":["Retorna uma entrega no prazo definido.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":2,"title":"Classifique 0 como no prazo e valores positivos como atraso","prompt":"Classifique 0 como no prazo e valores positivos como atraso.","hint":"Use duas saídas textuais.","solution":"SELECT id,CASE WHEN dias=0 THEN 'no prazo' ELSE 'atraso' END FROM entrega ORDER BY id;","criteria":["IDs 2 e 3 são classificados como atraso.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":3,"title":"Explique por que testar dias>=0 antes de dias>5 esconde a faixa maior","prompt":"Explique por que testar dias>=0 antes de dias>5 esconde a faixa maior.","hint":"CASE escolhe a primeira condição verdadeira.","solution":"Todo valor >5 já passa em >=0; teste primeiro a faixa específica ou torne os intervalos disjuntos.","criteria":["Explica a captura do valor 10 no primeiro ramo.","Registre o resultado e explique qual regra do banco o produziu."]}],"source":"https://www.sqlite.org/lang_expr.html","caution":"Laboratório em SQLite; verifique o dialeto ao migrar para outro SGBD. O editor salva o arquivo, mas a execução é local.","local":true,"hours":4,"minutes":45},{"id":13,"level":5,"title":"INNER JOIN e multiplicidade","goal":"Combinar relações sem perder de vista a quantidade de linhas.","theory":[{"title":"Combinar fatos","text":"INNER JOIN retorna combinações que satisfazem ON. Uma chave estrangeira ajuda a localizar o relacionamento, mas a junção precisa escrever a condição correta."},{"title":"Multiplicidade","text":"Uma pessoa com três empréstimos aparece em três linhas da junção. Isso é consequência da cardinalidade, não duplicação indevida do motor. DISTINCT não corrige automaticamente um indicador mal definido."},{"title":"Qualificar nomes","text":"Aliases curtos e colunas qualificadas evitam ambiguidade. Escreva o relacionamento por IDs, não por nomes que podem repetir."}],"code":"CREATE TABLE leitor(id INTEGER PRIMARY KEY,nome TEXT); CREATE TABLE emprestimo(id INTEGER PRIMARY KEY,leitor_id INTEGER);\nINSERT INTO leitor VALUES(1,'Ana'),(2,'Bia'); INSERT INTO emprestimo VALUES(10,1),(11,1);\nSELECT l.nome,e.id FROM leitor l JOIN emprestimo e ON e.leitor_id=l.id ORDER BY e.id;\n","filename":"aula.sql","language":"sql","run":"Abra uma sessão nova em memória: sqlite3 :memory:\nNo prompt, use .headers off e .mode list; depois .read aula.sql\nCada exemplo contém sua própria preparação e não depende da aula anterior.","expected":"Ana|10\nAna|11","quiz":{"question":"Ana aparece duas vezes na junção. Por quê?","options":["INNER JOIN sempre duplica tudo exatamente duas vezes.","Ela possui dois empréstimos correspondentes.","Os dados foram apagados.","O nome Ana é proibido."],"answer":1,"explanation":"A granularidade do resultado é uma linha por empréstimo correspondente."},"exercises":[{"id":1,"title":"Conte empréstimos por leitor com correspondência","prompt":"Conte empréstimos por leitor com correspondência.","hint":"Agrupe pela identidade do leitor.","solution":"SELECT l.id,COUNT(e.id) FROM leitor l JOIN emprestimo e ON e.leitor_id=l.id GROUP BY l.id; retorna 1|2.","criteria":["Conta dois empréstimos para o leitor 1.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":2,"title":"Remova ON e explique o risco","prompt":"Remova ON e explique o risco.","hint":"Considere todas as combinações.","solution":"O produto cartesiano combina cada leitor com cada empréstimo: 2×2=4 linhas; não representa os relacionamentos reais.","criteria":["Calcula quatro linhas e identifica a condição faltante.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":3,"title":"Conte leitores que têm empréstimo, sem contá-los repetidamente","prompt":"Conte leitores que têm empréstimo, sem contá-los repetidamente.","hint":"A pergunta é sobre leitores únicos.","solution":"SELECT COUNT(DISTINCT l.id) FROM leitor l JOIN emprestimo e ON e.leitor_id=l.id; retorna 1.","criteria":["Retorna um leitor, e não dois empréstimos.","Registre o resultado e explique qual regra do banco o produziu."]}],"source":"https://www.sqlite.org/lang_select.html","caution":"Laboratório em SQLite; verifique o dialeto ao migrar para outro SGBD. O editor salva o arquivo, mas a execução é local.","local":true,"hours":4,"minutes":45},{"id":14,"level":5,"title":"LEFT JOIN e linhas sem relação","goal":"Preservar entidades sem correspondência e contar corretamente.","theory":[{"title":"Preservar o lado esquerdo","text":"LEFT JOIN conserva cada linha esquerda e preenche a parte direita com NULL quando não há relação. Isso permite mostrar leitores ainda sem empréstimos."},{"title":"Filtro no lugar certo","text":"Uma condição da tabela direita em WHERE pode excluir as linhas sem correspondência e desfazer o efeito esperado da junção externa. Compare filtrar a relação em ON e filtrar o resultado em WHERE."},{"title":"Contar correspondências","text":"Na junção externa COUNT(*) inclui a linha preservada. COUNT(e.id) conta apenas empréstimos com identificador presente, produzindo zero para quem não possui nenhum."}],"code":"CREATE TABLE leitor(id INTEGER PRIMARY KEY,nome TEXT); CREATE TABLE emprestimo(id INTEGER PRIMARY KEY,leitor_id INTEGER);\nINSERT INTO leitor VALUES(1,'Ana'),(2,'Bia'); INSERT INTO emprestimo VALUES(10,1);\nSELECT l.nome,COUNT(e.id) FROM leitor l LEFT JOIN emprestimo e ON e.leitor_id=l.id GROUP BY l.id,l.nome ORDER BY l.id;\n","filename":"aula.sql","language":"sql","run":"Abra uma sessão nova em memória: sqlite3 :memory:\nNo prompt, use .headers off e .mode list; depois .read aula.sql\nCada exemplo contém sua própria preparação e não depende da aula anterior.","expected":"Ana|1\nBia|0","quiz":{"question":"Que contagem retorna zero para Bia neste exemplo?","options":["COUNT(*).","COUNT(l.id).","COUNT(e.id).","SUM(l.id)."],"answer":2,"explanation":"A parte direita ausente contém NULL, ignorado por COUNT(coluna)."},"exercises":[{"id":1,"title":"Liste apenas leitores sem empréstimos","prompt":"Liste apenas leitores sem empréstimos.","hint":"Teste a ausência da chave direita.","solution":"SELECT l.nome FROM leitor l LEFT JOIN emprestimo e ON e.leitor_id=l.id WHERE e.id IS NULL; retorna Bia.","criteria":["Retorna somente Bia.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":2,"title":"Compare COUNT(*) e COUNT(e","prompt":"Compare COUNT(*) e COUNT(e.id) por leitor.","hint":"A linha preservada ainda existe.","solution":"Bia tem COUNT(*)=1 e COUNT(e.id)=0; Ana tem 1 nas duas medidas.","criteria":["Explica a diferença sem confundir com empréstimo real.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":3,"title":"Preserve todos os leitores e relacione só empréstimos com id>10","prompt":"Preserve todos os leitores e relacione só empréstimos com id>10.","hint":"Coloque o filtro da relação em ON.","solution":"LEFT JOIN emprestimo e ON e.leitor_id=l.id AND e.id>10 preserva Ana e Bia, ambas sem correspondência.","criteria":["Mantém duas linhas de leitores.","Registre o resultado e explique qual regra do banco o produziu."]}],"source":"https://www.sqlite.org/lang_select.html","caution":"Laboratório em SQLite; verifique o dialeto ao migrar para outro SGBD. O editor salva o arquivo, mas a execução é local.","local":true,"hours":4,"minutes":45},{"id":15,"level":5,"title":"EXISTS e perguntas de existência","goal":"Consultar presença ou ausência sem multiplicar o resultado.","theory":[{"title":"Uma pergunta booleana","text":"EXISTS testa se a subconsulta encontra pelo menos uma linha. Use-o quando a pergunta é se um leitor tem algum empréstimo, sem precisar das colunas de cada empréstimo."},{"title":"Correlação","text":"A subconsulta pode se referir ao leitor da linha externa. A condição de correlação liga os dois escopos; esquecê-la transforma a pergunta por leitor em uma pergunta global."},{"title":"Ausência e NULL","text":"NOT EXISTS é uma forma clara de consultar ausência. NOT IN com uma lista contendo NULL pode produzir desconhecido; não trate as duas formas como sempre equivalentes."}],"code":"CREATE TABLE leitor(id INTEGER PRIMARY KEY); CREATE TABLE emprestimo(leitor_id INTEGER);\nINSERT INTO leitor VALUES(1),(2); INSERT INTO emprestimo VALUES(1),(1),(NULL);\nSELECT l.id FROM leitor l WHERE NOT EXISTS(SELECT 1 FROM emprestimo e WHERE e.leitor_id=l.id) ORDER BY l.id;\n","filename":"aula.sql","language":"sql","run":"Abra uma sessão nova em memória: sqlite3 :memory:\nNo prompt, use .headers off e .mode list; depois .read aula.sql\nCada exemplo contém sua própria preparação e não depende da aula anterior.","expected":"2","quiz":{"question":"NOT EXISTS correlacionado retorna o leitor 2 mesmo com NULL em emprestimo?","options":["Não, NULL elimina qualquer uso de EXISTS.","Não, retorna todos os empréstimos.","Sim, porque NULL é igual a 2.","Sim, ele testa a existência de uma correspondência para cada leitor."],"answer":3,"explanation":"A correlação é por igualdade de IDs; a linha nula não corresponde a 2."},"exercises":[{"id":1,"title":"Liste leitores com pelo menos um empréstimo","prompt":"Liste leitores com pelo menos um empréstimo.","hint":"Use EXISTS, sem NOT.","solution":"SELECT l.id FROM leitor l WHERE EXISTS(SELECT 1 FROM emprestimo e WHERE e.leitor_id=l.id); retorna 1.","criteria":["O leitor 1 aparece apenas uma vez.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":2,"title":"Compare id NOT IN(SELECT leitor_id FROM emprestimo)","prompt":"Compare id NOT IN(SELECT leitor_id FROM emprestimo).","hint":"Há um NULL no conjunto.","solution":"A consulta não encontra o leitor 2: o NULL torna a condição desconhecida. NOT EXISTS exprime melhor a ausência neste caso.","criteria":["Demonstra a diferença com o NULL presente.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":3,"title":"Remova a correlação e descreva o erro lógico","prompt":"Remova a correlação e descreva o erro lógico.","hint":"A subconsulta deixa de depender do leitor externo.","solution":"EXISTS passa a ser verdadeiro para todos os leitores porque existe algum empréstimo no banco, mesmo que não pertença àquele leitor.","criteria":["Explica por que o leitor 2 entra indevidamente.","Registre o resultado e explique qual regra do banco o produziu."]}],"source":"https://www.sqlite.org/lang_expr.html","caution":"Laboratório em SQLite; verifique o dialeto ao migrar para outro SGBD. O editor salva o arquivo, mas a execução é local.","local":true,"hours":4,"minutes":45},{"id":16,"level":6,"title":"Dependências funcionais","goal":"Reconhecer qual atributo determina cada fato do domínio.","theory":[{"title":"Conceito","text":"Uma dependência X→Y significa que, nas regras do domínio, o mesmo X sempre determina o mesmo Y. Ela não é provada por uma amostra pequena de linhas; precisa de uma regra de negócio."},{"title":"Aplicação","text":"Se codigo_curso determina nome_curso, repetir o nome a cada matrícula cria oportunidades de divergência. Separe curso e matrícula, conservando o relacionamento por código."},{"title":"Verificação","text":"Uma consulta de detecção encontra violações nos dados observados; resultado vazio não prova que o desenho está correto para todo dado futuro."}],"code":"CREATE TABLE matricula(aluno INTEGER,curso INTEGER,nome_curso TEXT);\nINSERT INTO matricula VALUES(1,10,'SQL'),(2,10,'SQL básico');\nSELECT curso,COUNT(DISTINCT nome_curso) FROM matricula GROUP BY curso HAVING COUNT(DISTINCT nome_curso)>1;\n","filename":"aula.sql","language":"sql","run":"Abra uma sessão nova em memória: sqlite3 :memory:\nNo prompt, use .headers off e .mode list; depois .read aula.sql\nCada exemplo contém sua própria preparação e não depende da aula anterior.","expected":"10|2","quiz":{"question":"A amostra sem divergências prova uma dependência funcional para todo o domínio?","options":["Não; a dependência depende da regra do domínio.","Sim, duas linhas bastam.","Sim, COUNT sempre prova regras futuras.","Não, porque SQL não agrupa texto."],"answer":0,"explanation":"Testes detectam violações observadas; a regra precisa ser definida."},"exercises":[{"id":1,"title":"Corrija a divergência do curso 10","prompt":"Corrija a divergência do curso 10.","hint":"Escolha um nome oficial e atualize ambas as ocorrências.","solution":"UPDATE matricula SET nome_curso='SQL' WHERE curso=10; a consulta de divergência fica vazia.","criteria":["O curso 10 possui um único nome distinto.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":2,"title":"Proponha a decomposição do esquema","prompt":"Proponha a decomposição do esquema.","hint":"Guarde cada fato no lugar determinado por sua chave.","solution":"curso(id PRIMARY KEY,nome) e matricula(aluno_id,curso_id) com FK; nome fica só em curso.","criteria":["Nome não é repetido em matrícula.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":3,"title":"Diferencie dependência de coincidência","prompt":"Diferencie dependência de coincidência.","hint":"Dois alunos podem morar na mesma cidade sem cidade determinar aluno.","solution":"Dados iguais na amostra não estabelecem identidade; descreva a regra que garante a determinação.","criteria":["Apresenta uma regra de domínio, além dos exemplos.","Registre o resultado e explique qual regra do banco o produziu."]}],"source":"https://www.sqlite.org/lang_select.html","caution":"Laboratório em SQLite; verifique o dialeto ao migrar para outro SGBD. O editor salva o arquivo, mas a execução é local.","local":true,"hours":4,"minutes":45},{"id":17,"level":6,"title":"Normalização e anomalias","goal":"Separar fatos que causam anomalias de atualização, inserção e exclusão.","theory":[{"title":"Conceito","text":"Normalizar organiza relações segundo suas dependências. Na 1FN os atributos contêm valores do domínio, sem grupos repetidos; a noção de valor depende do uso pretendido."},{"title":"Aplicação","text":"Na 2FN atributos não chave não dependem apenas de parte de uma chave candidata composta. Na 3FN, para cada dependência não trivial X→A, X é superchave ou A é atributo primo. A regra prática de evitar fatos transitivos ajuda nos casos simples, mas não substitui a definição."},{"title":"Verificação","text":"Decompor precisa preservar informação e, quando possível, restrições. Reconstituir a relação por junção e testar regras evita fragmentar dados sem um relacionamento válido."}],"code":"CREATE TABLE curso(id INTEGER PRIMARY KEY,nome TEXT NOT NULL);\nCREATE TABLE matricula(aluno INTEGER NOT NULL,curso INTEGER NOT NULL REFERENCES curso(id),PRIMARY KEY(aluno,curso));\nINSERT INTO curso VALUES(10,'SQL'); INSERT INTO matricula VALUES(1,10),(2,10);\nUPDATE curso SET nome='SQL e modelagem' WHERE id=10;\nSELECT m.aluno,c.nome FROM matricula m JOIN curso c ON c.id=m.curso ORDER BY m.aluno;\n","filename":"aula.sql","language":"sql","run":"Abra uma sessão nova em memória: sqlite3 :memory:\nNo prompt, use .headers off e .mode list; depois .read aula.sql\nCada exemplo contém sua própria preparação e não depende da aula anterior.","expected":"1|SQL e modelagem\n2|SQL e modelagem","quiz":{"question":"Qual anomalia é evitada ao guardar nome do curso em uma única linha de curso?","options":["Ter mais de um aluno.","Atualizar o nome de forma contraditória em matrículas diferentes.","Usar chaves estrangeiras.","Consultar duas tabelas."],"answer":1,"explanation":"A atualização passa a modificar a fonte do fato."},"exercises":[{"id":1,"title":"Cadastre um curso sem aluno matriculado","prompt":"Cadastre um curso sem aluno matriculado.","hint":"A entidade curso existe independentemente da associação.","solution":"INSERT INTO curso VALUES(20,'Redes'); funciona sem criar matrícula.","criteria":["O curso existe com zero matrículas.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":2,"title":"Remova todas as matrículas do curso 10","prompt":"Remova todas as matrículas do curso 10.","hint":"Excluir associação não deve apagar o curso.","solution":"DELETE FROM matricula WHERE curso=10; SELECT nome FROM curso WHERE id=10; ainda retorna SQL e modelagem.","criteria":["O nome do curso é preservado.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":3,"title":"Identifique dependência parcial numa chave (pedido_id,produto_id) com nome_produto","prompt":"Identifique dependência parcial numa chave (pedido_id,produto_id) com nome_produto.","hint":"Nome depende do produto, não do par.","solution":"Extraia produto(id,nome); mantenha quantidade e preço contratado no item do pedido.","criteria":["Distingue nome do produto de preço histórico do item.","Registre o resultado e explique qual regra do banco o produziu."]}],"source":"https://www.sqlite.org/lang_createtable.html","caution":"Laboratório em SQLite; verifique o dialeto ao migrar para outro SGBD. O editor salva o arquivo, mas a execução é local.","local":true,"hours":4,"minutes":45},{"id":18,"level":6,"title":"Desnormalização com responsabilidade","goal":"Avaliar redundância intencional e medir sua manutenção.","theory":[{"title":"Conceito","text":"Desnormalização guarda uma informação derivada para atender uma necessidade medida, como um resumo consultado com frequência. Ela exige uma política explícita de atualização e reconciliação."},{"title":"Aplicação","text":"Comece com uma consulta que calcula a verdade a partir dos fatos. Depois compare o valor armazenado com o calculado. Esse teste expõe resumos desatualizados."},{"title":"Verificação","text":"Um cache de total não é fonte independente de receita. Determine latência aceitável, responsável pela atualização e como reconstruir o resumo; desempenho não justifica divergência desconhecida."}],"code":"CREATE TABLE item(valor INTEGER); CREATE TABLE resumo(total INTEGER);\nINSERT INTO item VALUES(100),(200); INSERT INTO resumo VALUES(250);\nSELECT r.total,(SELECT SUM(valor) FROM item) AS calculado FROM resumo r;\n","filename":"aula.sql","language":"sql","run":"Abra uma sessão nova em memória: sqlite3 :memory:\nNo prompt, use .headers off e .mode list; depois .read aula.sql\nCada exemplo contém sua própria preparação e não depende da aula anterior.","expected":"250|300","quiz":{"question":"Qual obrigação surge ao armazenar um total derivado?","options":["Apagar todos os fatos de origem.","Garantir que nunca exista JOIN.","Manter ou reconstruir sua consistência com os fatos.","Remover testes."],"answer":2,"explanation":"A redundância cria uma responsabilidade de manutenção."},"exercises":[{"id":1,"title":"Reconcilie o resumo com os itens","prompt":"Reconcilie o resumo com os itens.","hint":"Use uma subconsulta agregada.","solution":"UPDATE resumo SET total=(SELECT SUM(valor) FROM item); retorna depois 300|300.","criteria":["Os dois totais passam a 300.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":2,"title":"Defina um indicador de divergência","prompt":"Defina um indicador de divergência.","hint":"Compare calculado e armazenado.","solution":"SELECT total-(SELECT SUM(valor) FROM item) FROM resumo; zero significa coincidência nesta verificação.","criteria":["O indicador vale zero após reconciliar.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":3,"title":"Proponha uma regra de atualização para relatório diário","prompt":"Proponha uma regra de atualização para relatório diário.","hint":"A frequência deve corresponder à tolerância de atraso.","solution":"Reconstruir ao fechar o dia, registrar horário de referência e reconciliar antes de publicar; documentar que o relatório não é instantâneo.","criteria":["Explicita horário, atraso e reconciliação.","Registre o resultado e explique qual regra do banco o produziu."]}],"source":"https://www.sqlite.org/lang_select.html","caution":"Laboratório em SQLite; verifique o dialeto ao migrar para outro SGBD. O editor salva o arquivo, mas a execução é local.","local":true,"hours":4,"minutes":45},{"id":19,"level":7,"title":"INSERT e conflitos","goal":"Inserir registros com intenção clara e tratar duplicações.","theory":[{"title":"Conceito","text":"INSERT escreve fatos e deve indicar as colunas. Um lote inteiro pode falhar por uma constraint; a estratégia de erro precisa ser definida pelo cliente."},{"title":"Aplicação","text":"Chaves únicas permitem detectar tentativas duplicadas. ON CONFLICT do laboratório pode ignorar ou atualizar o conflito escolhido; não ignore toda falha como se fosse sucesso."},{"title":"Verificação","text":"Verifique a linha final e a quantidade de efeitos, especialmente quando a aplicação repete uma requisição após timeout."}],"code":"CREATE TABLE registro(chave TEXT PRIMARY KEY NOT NULL,valor INTEGER NOT NULL);\nINSERT INTO registro VALUES('r1',100);\nINSERT INTO registro VALUES('r1',200) ON CONFLICT(chave) DO NOTHING;\nSELECT chave,valor FROM registro;\n","filename":"aula.sql","language":"sql","run":"Abra uma sessão nova em memória: sqlite3 :memory:\nNo prompt, use .headers off e .mode list; depois .read aula.sql\nCada exemplo contém sua própria preparação e não depende da aula anterior.","expected":"r1|100","quiz":{"question":"O segundo INSERT com DO NOTHING substitui 100 por 200?","options":["Sim, sempre.","Sim, se não houver ORDER BY.","Ele apaga a tabela.","Não, a linha existente permanece com 100."],"answer":3,"explanation":"A ação de conflito é explícita."},"exercises":[{"id":1,"title":"Faça o conflito atualizar valor para 200","prompt":"Faça o conflito atualizar valor para 200.","hint":"Use DO UPDATE no conflito da chave.","solution":"INSERT INTO registro VALUES('r1',200) ON CONFLICT(chave) DO UPDATE SET valor=excluded.valor;","criteria":["r1 termina com valor 200.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":2,"title":"Cadastre r2 sem conflito","prompt":"Cadastre r2 sem conflito.","hint":"A chave nova deve criar uma linha.","solution":"INSERT INTO registro(chave,valor) VALUES('r2',300);","criteria":["Existem duas chaves distintas.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":3,"title":"Explique por que ignorar conflitos pode esconder uma requisição diferente","prompt":"Explique por que ignorar conflitos pode esconder uma requisição diferente.","hint":"Compare conteúdo original e conteúdo repetido.","solution":"A mesma chave com valor diferente pode ser erro de cliente; uma API idempotente deve verificar se o conteúdo corresponde à primeira operação.","criteria":["Distingue repetição idêntica de reutilização incorreta de chave.","Registre o resultado e explique qual regra do banco o produziu."]}],"source":"https://www.sqlite.org/lang_upsert.html","caution":"Laboratório em SQLite; verifique o dialeto ao migrar para outro SGBD. O editor salva o arquivo, mas a execução é local.","local":true,"hours":4,"minutes":45},{"id":20,"level":7,"title":"UPDATE e alteração controlada","goal":"Modificar apenas o conjunto desejado e verificar o efeito.","theory":[{"title":"Conceito","text":"UPDATE aplica a alteração a todas as linhas que atendem ao WHERE. Sem WHERE, todas são candidatas. Antes de modificar, escreva um SELECT com o mesmo predicado."},{"title":"Aplicação","text":"Prefira condições que identifiquem a versão ou o estado esperado quando houver concorrência. Um resultado de zero linhas pode significar conflito, ausência ou regra não atendida."},{"title":"Verificação","text":"O teste precisa cobrir linha alvo, linha não alvo e caso em que o predicado não é atendido. A quantidade de linhas alteradas é parte da verificação."}],"code":"CREATE TABLE item(id INTEGER PRIMARY KEY,estoque INTEGER NOT NULL CHECK(estoque>=0));\nINSERT INTO item VALUES(1,5),(2,8);\nUPDATE item SET estoque=estoque-2 WHERE id=1 AND estoque>=2;\nSELECT id,estoque FROM item ORDER BY id;\n","filename":"aula.sql","language":"sql","run":"Abra uma sessão nova em memória: sqlite3 :memory:\nNo prompt, use .headers off e .mode list; depois .read aula.sql\nCada exemplo contém sua própria preparação e não depende da aula anterior.","expected":"1|3\n2|8","quiz":{"question":"O predicado estoque>=2 protege qual condição?","options":["Só reduzir quando há estoque suficiente para essa baixa.","Impede qualquer leitura.","Ordena por estoque.","Cria dois produtos."],"answer":0,"explanation":"A condição da escrita expressa o estado necessário."},"exercises":[{"id":1,"title":"Tente baixar 10 do item 1","prompt":"Tente baixar 10 do item 1.","hint":"Use o mesmo padrão com quantidade 10.","solution":"UPDATE item SET estoque=estoque-10 WHERE id=1 AND estoque>=10; não altera linha; estoque permanece 3.","criteria":["Nenhuma linha muda e não há estoque negativo.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":2,"title":"Aumente apenas o estoque do item 2 em 4","prompt":"Aumente apenas o estoque do item 2 em 4.","hint":"Mantenha WHERE id=2.","solution":"UPDATE item SET estoque=estoque+4 WHERE id=2;","criteria":["O item 1 permanece 3 e o item 2 vai a 12.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":3,"title":"Explique o risco de ler estoque e depois gravar um valor calculado no cliente","prompt":"Explique o risco de ler estoque e depois gravar um valor calculado no cliente.","hint":"Outro cliente pode escrever entre as etapas.","solution":"Duas leituras do mesmo saldo podem gerar atualização perdida; use escrita condicional/atômica e tratamento de concorrência.","criteria":["Descreve uma intercalação de duas operações.","Registre o resultado e explique qual regra do banco o produziu."]}],"source":"https://www.sqlite.org/lang_update.html","caution":"Laboratório em SQLite; verifique o dialeto ao migrar para outro SGBD. O editor salva o arquivo, mas a execução é local.","local":true,"hours":4,"minutes":45},{"id":21,"level":7,"title":"DELETE e ciclo de vida","goal":"Distinguir exclusão física, inativação e retenção.","theory":[{"title":"Conceito","text":"DELETE remove linhas segundo um predicado. Uma exclusão pode ser impedida ou propagada por FKs; entenda as dependências antes de executá-la."},{"title":"Aplicação","text":"Inativar preserva a linha e altera seu estado, mas muda todas as consultas que precisam ignorar inativos. Isso também afeta unicidade, retenção e capacidade de recuperar o histórico."},{"title":"Verificação","text":"Defina o ciclo de vida do dado: criação, uso, arquivamento e descarte. Um campo ativo não substitui política de recuperação nem retenção."}],"code":"CREATE TABLE leitor(id INTEGER PRIMARY KEY,ativo INTEGER NOT NULL CHECK(ativo IN(0,1)));\nINSERT INTO leitor VALUES(1,1),(2,1),(3,1);\nUPDATE leitor SET ativo=0 WHERE id=2;\nDELETE FROM leitor WHERE id=3;\nSELECT id,ativo FROM leitor ORDER BY id;\n","filename":"aula.sql","language":"sql","run":"Abra uma sessão nova em memória: sqlite3 :memory:\nNo prompt, use .headers off e .mode list; depois .read aula.sql\nCada exemplo contém sua própria preparação e não depende da aula anterior.","expected":"1|1\n2|0","quiz":{"question":"Qual registro continua armazenado após a inativação do exemplo?","options":["O leitor 3, com ativo=1.","O leitor 2, com ativo=0.","Nenhum leitor.","Uma nova linha de leitor 4."],"answer":1,"explanation":"Inativação e exclusão possuem efeitos diferentes."},"exercises":[{"id":1,"title":"Liste somente leitores ativos","prompt":"Liste somente leitores ativos.","hint":"A regra é um filtro de estado.","solution":"SELECT id FROM leitor WHERE ativo=1 ORDER BY id; retorna 1.","criteria":["O leitor 2 não aparece na visão de ativos.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":2,"title":"Reative o leitor 2","prompt":"Reative o leitor 2.","hint":"Atualize a linha preservada.","solution":"UPDATE leitor SET ativo=1 WHERE id=2;","criteria":["O ID 2 volta à listagem de ativos.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":3,"title":"Descreva um risco de CASCADE em históricos","prompt":"Descreva um risco de CASCADE em históricos.","hint":"Uma exclusão no pai pode afetar muitas linhas.","solution":"Apagar leitor com ON DELETE CASCADE poderia apagar empréstimos usados em auditoria; prefira uma regra de retenção adequada ao domínio.","criteria":["Identifica a perda de histórico e a ação causadora.","Registre o resultado e explique qual regra do banco o produziu."]}],"source":"https://www.sqlite.org/lang_delete.html","caution":"Laboratório em SQLite; verifique o dialeto ao migrar para outro SGBD. O editor salva o arquivo, mas a execução é local.","local":true,"hours":4,"minutes":45},{"id":22,"level":8,"title":"Subconsultas e comparação com medidas","goal":"Comparar linhas com uma medida calculada sobre o conjunto.","theory":[{"title":"Conceito","text":"Uma subconsulta pode produzir um valor escalar, uma relação ou um teste de existência. Use a forma correspondente à pergunta."},{"title":"Aplicação","text":"Para preços acima da média, calcule a média do conjunto de referência e compare cada linha com esse valor. Não confunda a média global com a média por categoria."},{"title":"Verificação","text":"Uma subconsulta escalar deve ter cardinalidade bem definida. O tratamento de múltiplas linhas varia por motor; não dependa de uma escolha arbitrária do laboratório."}],"code":"CREATE TABLE livro(id INTEGER PRIMARY KEY,preco INTEGER);\nINSERT INTO livro VALUES(1,100),(2,200),(3,600);\nSELECT id FROM livro WHERE preco>(SELECT AVG(preco) FROM livro) ORDER BY id;\n","filename":"aula.sql","language":"sql","run":"Abra uma sessão nova em memória: sqlite3 :memory:\nNo prompt, use .headers off e .mode list; depois .read aula.sql\nCada exemplo contém sua própria preparação e não depende da aula anterior.","expected":"3","quiz":{"question":"A média calculada sem GROUP BY nesta subconsulta corresponde a quê?","options":["À média exclusiva de cada linha.","Ao maior ID.","Ao conjunto global de livros consultado.","Ao primeiro livro por ordem física."],"answer":2,"explanation":"O escopo da subconsulta define o conjunto de referência."},"exercises":[{"id":1,"title":"Calcule a média explicitamente","prompt":"Calcule a média explicitamente.","hint":"Some e divida pela quantidade de valores conhecidos.","solution":"SELECT AVG(preco) FROM livro; retorna 300.0.","criteria":["Demonstra a média 300.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":2,"title":"Encontre livros com o maior preço","prompt":"Encontre livros com o maior preço.","hint":"Compare com MAX.","solution":"SELECT id FROM livro WHERE preco=(SELECT MAX(preco) FROM livro); retorna 3.","criteria":["Trata também empates caso outro livro tenha 600.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":3,"title":"Inclua outro livro de preço 600 e compare =MAX com LIMIT 1","prompt":"Inclua outro livro de preço 600 e compare =MAX com LIMIT 1.","hint":"Empates mudam a cardinalidade da resposta.","solution":"=MAX retorna os dois mais caros; ORDER BY preco DESC,id LIMIT 1 escolhe apenas um segundo o desempate.","criteria":["Distingue todos os empatados de um único resultado.","Registre o resultado e explique qual regra do banco o produziu."]}],"source":"https://www.sqlite.org/lang_expr.html","caution":"Laboratório em SQLite; verifique o dialeto ao migrar para outro SGBD. O editor salva o arquivo, mas a execução é local.","local":true,"hours":4,"minutes":45},{"id":23,"level":8,"title":"CTEs e decomposição da consulta","goal":"Nomear etapas de uma consulta para torná-la verificável.","theory":[{"title":"Conceito","text":"WITH define uma expressão de tabela comum no escopo de uma instrução. CTE não é automaticamente uma tabela persistente ou uma garantia de materialização."},{"title":"Aplicação","text":"Nomeie etapas pelo significado: totais_por_leitor deixa mais clara a granularidade que uma sequência longa de subconsultas anônimas."},{"title":"Verificação","text":"Verifique cada etapa separadamente durante a investigação. Melhor legibilidade não garante maior velocidade; o plano e a medição determinam o efeito operacional."}],"code":"CREATE TABLE emprestimo(leitor_id INTEGER,quantidade INTEGER);\nINSERT INTO emprestimo VALUES(1,2),(1,1),(2,1);\nWITH totais AS(SELECT leitor_id,SUM(quantidade) total FROM emprestimo GROUP BY leitor_id) SELECT leitor_id,total FROM totais WHERE total>=2 ORDER BY leitor_id;\n","filename":"aula.sql","language":"sql","run":"Abra uma sessão nova em memória: sqlite3 :memory:\nNo prompt, use .headers off e .mode list; depois .read aula.sql\nCada exemplo contém sua própria preparação e não depende da aula anterior.","expected":"1|3","quiz":{"question":"Uma CTE de uma instrução fica disponível em outro SELECT executado depois?","options":["Sim, para sempre.","Sim, até reiniciar o computador.","Somente se chamar totais.","Não; seu escopo é a instrução que a declara."],"answer":3,"explanation":"CTEs organizam uma instrução; persistência precisa de outro mecanismo."},"exercises":[{"id":1,"title":"Mostre a etapa totais sem o filtro final","prompt":"Mostre a etapa totais sem o filtro final.","hint":"Mantenha WITH e consulte todas as linhas da CTE.","solution":"WITH totais AS(SELECT leitor_id,SUM(quantidade) total FROM emprestimo GROUP BY leitor_id) SELECT * FROM totais ORDER BY leitor_id; retorna 1|3 e 2|1.","criteria":["As duas linhas possuem a granularidade por leitor.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":2,"title":"Troque a medida por quantidade de empréstimos","prompt":"Troque a medida por quantidade de empréstimos.","hint":"COUNT(*) conta linhas, não quantidade somada.","solution":"Use COUNT(*) AS total; leitor 1 terá 2 e leitor 2 terá 1.","criteria":["Distingue duas operações de três unidades.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":3,"title":"Explique por que uma CTE não prova melhoria de desempenho","prompt":"Explique por que uma CTE não prova melhoria de desempenho.","hint":"A implementação depende do otimizador e da consulta.","solution":"O motor pode incorporar ou materializar etapas conforme suas regras; compare planos e medições do mesmo trabalho.","criteria":["Cita plano e medição em vez de inferir velocidade pela sintaxe.","Registre o resultado e explique qual regra do banco o produziu."]}],"source":"https://www.sqlite.org/lang_with.html","caution":"Laboratório em SQLite; verifique o dialeto ao migrar para outro SGBD. O editor salva o arquivo, mas a execução é local.","local":true,"hours":4,"minutes":45},{"id":24,"level":8,"title":"Funções de janela","goal":"Calcular ranking e acumulados preservando linhas de detalhe.","theory":[{"title":"Conceito","text":"Uma janela calcula uma medida sobre linhas relacionadas sem reduzir tudo a uma linha por grupo. OVER distingue essa operação de uma agregação comum."},{"title":"Aplicação","text":"PARTITION BY separa grupos e ORDER BY define sequência dentro da janela. A ordem da janela não dispensa ORDER BY no resultado final."},{"title":"Verificação","text":"Para acumulados, declare ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW e um desempate quando necessário. Frames implícitos podem tratar empates de modo diferente do esperado."}],"code":"CREATE TABLE movimento(id INTEGER PRIMARY KEY,valor INTEGER);\nINSERT INTO movimento VALUES(1,100),(2,200),(3,-50);\nSELECT id,valor,SUM(valor) OVER(ORDER BY id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) saldo FROM movimento ORDER BY id;\n","filename":"aula.sql","language":"sql","run":"Abra uma sessão nova em memória: sqlite3 :memory:\nNo prompt, use .headers off e .mode list; depois .read aula.sql\nCada exemplo contém sua própria preparação e não depende da aula anterior.","expected":"1|100|100\n2|200|300\n3|-50|250","quiz":{"question":"A janela SUM do exemplo reduz três movimentos a uma linha?","options":["Não; conserva três linhas com o saldo acumulado em cada uma.","Sim, qualquer SUM elimina detalhes.","Sim, OVER é sinônimo de GROUP BY.","Não, ela cria uma tabela nova."],"answer":0,"explanation":"A janela acrescenta uma medida sem mudar a granularidade do detalhe."},"exercises":[{"id":1,"title":"Troque SUM por ROW_NUMBER no exemplo","prompt":"Troque SUM por ROW_NUMBER no exemplo.","hint":"ROW_NUMBER não recebe valor como argumento.","solution":"SELECT id,ROW_NUMBER() OVER(ORDER BY id) FROM movimento ORDER BY id; produz 1,2,3 como numeração.","criteria":["Cada movimento recebe posição única.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":2,"title":"Acrescente movimento 4 de valor 20 e calcule saldo final","prompt":"Acrescente movimento 4 de valor 20 e calcule saldo final.","hint":"O saldo anterior é 250.","solution":"INSERT INTO movimento VALUES(4,20); o último acumulado passa a 270.","criteria":["O último saldo é 270.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":3,"title":"Explique por que ordenar só por valor pode gerar saldo não estável em empates","prompt":"Explique por que ordenar só por valor pode gerar saldo não estável em empates.","hint":"Movimentos com mesmo valor precisam de desempate se a sequência importar.","solution":"Inclua um identificador estável, por exemplo ORDER BY valor,id, e declare o frame pretendido.","criteria":["Inclui desempate e define a semântica do frame.","Registre o resultado e explique qual regra do banco o produziu."]}],"source":"https://www.sqlite.org/windowfunctions.html","caution":"Laboratório em SQLite; verifique o dialeto ao migrar para outro SGBD. O editor salva o arquivo, mas a execução é local.","local":true,"hours":4,"minutes":45},{"id":25,"level":9,"title":"Transações e atomicidade","goal":"Agrupar alterações que devem confirmar ou desfazer juntas.","theory":[{"title":"Conceito","text":"Uma transação estabelece uma unidade de trabalho. Atomicidade evita conservar apenas parte da operação; consistência depende também de regras corretas; isolamento coordena concorrência e durabilidade depende da configuração e do armazenamento."},{"title":"Aplicação","text":"BEGIN, COMMIT e ROLLBACK controlam o laboratório. O modo de autocommit e o tratamento de erros variam conforme driver e motor; a aplicação precisa tratar falhas explicitamente."},{"title":"Verificação","text":"Faça um teste de falha depois da primeira alteração e antes da segunda. O estado final deve representar a operação inteira ou sua ausência, nunca uma metade."}],"code":"CREATE TABLE conta(id INTEGER PRIMARY KEY,saldo INTEGER CHECK(saldo>=0));\nINSERT INTO conta VALUES(1,100),(2,50);\nBEGIN; UPDATE conta SET saldo=saldo-20 WHERE id=1; UPDATE conta SET saldo=saldo+20 WHERE id=2; ROLLBACK;\nSELECT id,saldo FROM conta ORDER BY id;\n","filename":"aula.sql","language":"sql","run":"Abra uma sessão nova em memória: sqlite3 :memory:\nNo prompt, use .headers off e .mode list; depois .read aula.sql\nCada exemplo contém sua própria preparação e não depende da aula anterior.","expected":"1|100\n2|50","quiz":{"question":"Qual é o saldo da conta 1 depois do ROLLBACK?","options":["80.","100, pois a alteração foi desfeita.","120.","NULL obrigatoriamente."],"answer":1,"explanation":"ROLLBACK desfaz a unidade de trabalho ainda não confirmada."},"exercises":[{"id":1,"title":"Troque ROLLBACK por COMMIT","prompt":"Troque ROLLBACK por COMMIT.","hint":"Ambas as alterações serão confirmadas.","solution":"Os saldos finais serão 80 e 70, mantendo total 150.","criteria":["Os dois saldos e a soma são verificados.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":2,"title":"Faça apenas a primeira alteração e execute ROLLBACK","prompt":"Faça apenas a primeira alteração e execute ROLLBACK.","hint":"A conta destino não precisa ser alterada para testar desfazer.","solution":"O saldo da conta 1 volta a 100 e o da conta 2 permanece 50.","criteria":["Nenhuma metade de transferência persiste.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":3,"title":"Explique por que uma transação não valida sozinha o destinatário","prompt":"Explique por que uma transação não valida sozinha o destinatário.","hint":"Atomicidade não corrige regra ausente.","solution":"Se UPDATE do destino não encontra linha e o cliente ignora isso, pode confirmar um débito sem crédito; confira quantidade de efeitos e invariantes.","criteria":["Inclui verificação do destinatário e do efeito.","Registre o resultado e explique qual regra do banco o produziu."]}],"source":"https://www.sqlite.org/lang_transaction.html","caution":"Laboratório em SQLite; verifique o dialeto ao migrar para outro SGBD. O editor salva o arquivo, mas a execução é local.","local":true,"hours":4,"minutes":45},{"id":26,"level":9,"title":"Savepoints e recuperação parcial","goal":"Desfazer uma etapa opcional sem confirmar a operação externa.","theory":[{"title":"Conceito","text":"SAVEPOINT marca um ponto dentro da transação. ROLLBACK TO desfaz alterações posteriores a ele, mantendo a transação ativa. RELEASE remove a marca; em uma transação externa explícita não equivale ao COMMIT externo."},{"title":"Aplicação","text":"Essa estrutura ajuda em etapas opcionais, como registrar uma tentativa auxiliar, quando o domínio permite preservação parcial. Se toda a operação deve ser indivisível, não use recuperação parcial para esconder erro essencial."},{"title":"Verificação","text":"Teste o estado após ROLLBACK TO e novamente após o COMMIT externo. O escopo do desfazer deve estar claro para quem lê o código."}],"code":"CREATE TABLE log(msg TEXT);\nBEGIN; INSERT INTO log VALUES('principal'); SAVEPOINT opcional; INSERT INTO log VALUES('extra'); ROLLBACK TO opcional; RELEASE opcional; COMMIT;\nSELECT msg FROM log;\n","filename":"aula.sql","language":"sql","run":"Abra uma sessão nova em memória: sqlite3 :memory:\nNo prompt, use .headers off e .mode list; depois .read aula.sql\nCada exemplo contém sua própria preparação e não depende da aula anterior.","expected":"principal","quiz":{"question":"Que mensagem sobrevive após o exemplo?","options":["extra apenas.","As duas.","principal.","Nenhuma, pois RELEASE sempre apaga tudo."],"answer":2,"explanation":"O rollback parcial remove somente as alterações posteriores à marca."},"exercises":[{"id":1,"title":"Remova ROLLBACK TO e compare","prompt":"Remova ROLLBACK TO e compare.","hint":"As duas inserções permanecem no mesmo commit.","solution":"O resultado passa a principal e extra.","criteria":["As duas mensagens são observadas.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":2,"title":"Execute ROLLBACK externo em vez de COMMIT","prompt":"Execute ROLLBACK externo em vez de COMMIT.","hint":"A transação externa ainda reúne todo o trabalho.","solution":"Nenhuma mensagem fica armazenada.","criteria":["O log termina vazio.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":3,"title":"Dê um exemplo em que rollback parcial seria incorreto","prompt":"Dê um exemplo em que rollback parcial seria incorreto.","hint":"Pense em etapas obrigatórias de uma transferência.","solution":"Confirmar débito e desfazer apenas o crédito viola a operação; nesse caso desfaça a transação inteira.","criteria":["Relaciona o escopo ao invariante do domínio.","Registre o resultado e explique qual regra do banco o produziu."]}],"source":"https://www.sqlite.org/lang_savepoint.html","caution":"Laboratório em SQLite; verifique o dialeto ao migrar para outro SGBD. O editor salva o arquivo, mas a execução é local.","local":true,"hours":4,"minutes":45},{"id":27,"level":9,"title":"Concorrência, repetição e idempotência","goal":"Preparar escritas para disputa e repetição após resultado incerto.","theory":[{"title":"Conceito","text":"Duas requisições podem disputar o mesmo recurso. Uma atualização condicionada à versão detecta que o estado mudou desde a leitura. Não use espera na interface como mecanismo de sincronização."},{"title":"Aplicação","text":"Após timeout, o cliente pode não saber se houve commit. Uma chave idempotente única permite reconhecer a operação repetida; deve estar na mesma unidade de trabalho dos efeitos."},{"title":"Verificação","text":"Retries precisam ser limitados e adequados ao erro. Conflito de negócio não se resolve repetindo cegamente. SQLite permite apenas um escritor por vez; outros motores têm mecanismos de isolamento diferentes."}],"code":"CREATE TABLE item(id INTEGER PRIMARY KEY,versao INTEGER,estoque INTEGER);\nINSERT INTO item VALUES(1,1,5);\nUPDATE item SET estoque=4,versao=versao+1 WHERE id=1 AND versao=1;\nUPDATE item SET estoque=3,versao=versao+1 WHERE id=1 AND versao=1;\nSELECT id,versao,estoque FROM item;\n","filename":"aula.sql","language":"sql","run":"Abra uma sessão nova em memória: sqlite3 :memory:\nNo prompt, use .headers off e .mode list; depois .read aula.sql\nCada exemplo contém sua própria preparação e não depende da aula anterior.","expected":"1|2|4","quiz":{"question":"Por que a segunda alteração do exemplo não ocorre?","options":["Porque SQL permite somente um UPDATE por arquivo.","Porque estoque=3 é inválido por definição.","Porque o ID foi excluído.","Ela exige versao=1, mas a primeira já mudou para 2."],"answer":3,"explanation":"O predicado detecta uma versão que ficou obsoleta."},"exercises":[{"id":1,"title":"Repita a segunda alteração exigindo versão 2","prompt":"Repita a segunda alteração exigindo versão 2.","hint":"Uma nova leitura observou a versão atual.","solution":"UPDATE item SET estoque=3,versao=3 WHERE id=1 AND versao=2; agora altera a linha.","criteria":["O estado final é versão 3 e estoque 3.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":2,"title":"Projete uma tabela de operações idempotentes","prompt":"Projete uma tabela de operações idempotentes.","hint":"Chave única e resultado da primeira operação precisam se relacionar.","solution":"operacao(chave TEXT PRIMARY KEY NOT NULL,hash_pedido TEXT NOT NULL,resultado TEXT); grave junto dos efeitos e compare o hash em repetições.","criteria":["Explicita unicidade, conteúdo e unidade transacional.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":3,"title":"Diferencie timeout de recusa de estoque","prompt":"Diferencie timeout de recusa de estoque.","hint":"Uma causa é incerteza técnica; a outra é regra de negócio.","solution":"Timeout pode exigir consulta à chave idempotente; estoque insuficiente exige comunicar o domínio, não repetir ilimitadamente.","criteria":["A estratégia de repetição é diferente para cada caso.","Registre o resultado e explique qual regra do banco o produziu."]}],"source":"https://www.sqlite.org/isolation.html","caution":"Laboratório em SQLite; verifique o dialeto ao migrar para outro SGBD. O editor salva o arquivo, mas a execução é local.","local":true,"hours":4,"minutes":45},{"id":28,"level":10,"title":"Índices e custo de escrita","goal":"Criar um índice alinhado a uma consulta e reconhecer seu custo.","theory":[{"title":"Conceito","text":"Um índice é uma estrutura auxiliar para localizar ou ordenar dados. Ele ocupa espaço e precisa ser mantido em inserções, alterações e exclusões."},{"title":"Aplicação","text":"Em um índice composto a ordem das colunas importa. Escolha a partir de predicados e ordenação reais, não da quantidade de colunas da tabela."},{"title":"Verificação","text":"Um índice não é uma promessa de uso pelo otimizador. Para tabelas pequenas, varredura pode ser uma opção adequada; avalie com volume e distribuição representativos."}],"code":"CREATE TABLE emprestimo(id INTEGER PRIMARY KEY,leitor_id INTEGER,aberto INTEGER);\nCREATE INDEX ix_emprestimo_leitor ON emprestimo(leitor_id);\nINSERT INTO emprestimo VALUES(1,10,1),(2,20,0);\nSELECT id FROM emprestimo WHERE leitor_id=10 ORDER BY id;\n","filename":"aula.sql","language":"sql","run":"Abra uma sessão nova em memória: sqlite3 :memory:\nNo prompt, use .headers off e .mode list; depois .read aula.sql\nCada exemplo contém sua própria preparação e não depende da aula anterior.","expected":"1","quiz":{"question":"Adicionar índices tem custo nas escritas?","options":["Sim; as estruturas também precisam ser atualizadas.","Não, só ocupam um comentário.","Não, existem apenas durante SELECT.","Só quando o banco está vazio."],"answer":0,"explanation":"Índices são dados auxiliares persistidos e mantidos pelo motor."},"exercises":[{"id":1,"title":"Crie índice composto para leitor_id e aberto","prompt":"Crie índice composto para leitor_id e aberto.","hint":"O primeiro filtro é pelo leitor.","solution":"CREATE INDEX ix_leitor_aberto ON emprestimo(leitor_id,aberto);","criteria":["A ordem do índice corresponde ao filtro descrito.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":2,"title":"Explique por que não criar um índice para cada coluna automaticamente","prompt":"Explique por que não criar um índice para cada coluna automaticamente.","hint":"Considere espaço e manutenção.","solution":"Índices redundantes aumentam custo sem necessariamente ajudar consultas; selecione pela carga observada.","criteria":["Cita custo de escrita e utilidade medida.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":3,"title":"Encontre os índices declarados no laboratório","prompt":"Encontre os índices declarados no laboratório.","hint":"O catálogo SQLite possui sqlite_schema.","solution":"SELECT name FROM sqlite_schema WHERE type='index' AND name LIKE 'ix_%' ORDER BY name;","criteria":["Lista os índices criados conscientemente.","Registre o resultado e explique qual regra do banco o produziu."]}],"source":"https://www.sqlite.org/lang_createindex.html","caution":"Laboratório em SQLite; verifique o dialeto ao migrar para outro SGBD. O editor salva o arquivo, mas a execução é local.","local":true,"hours":4,"minutes":45},{"id":29,"level":10,"title":"Planos e medições","goal":"Ler uma estratégia de acesso sem confundi-la com tempo garantido.","theory":[{"title":"Conceito","text":"EXPLAIN QUERY PLAN apresenta a estratégia planejada no SQLite. Procure varredura, pesquisa por índice e ordenação temporária. A apresentação pode mudar entre versões."},{"title":"Aplicação","text":"Um plano descreve como obter resultados; medições mostram custo sob uma carga. Use mesma consulta, mesmos dados e resultados corretos antes de comparar desempenho."},{"title":"Verificação","text":"Evite prometer tempos a partir de duas linhas. Cache, distribuição e concorrência alteram o comportamento; registre tamanho, versão e método do experimento."}],"code":"CREATE TABLE item(id INTEGER PRIMARY KEY,categoria TEXT);\nCREATE INDEX ix_categoria ON item(categoria);\nINSERT INTO item VALUES(1,'livro'),(2,'jogo');\nEXPLAIN QUERY PLAN SELECT id FROM item WHERE categoria='livro';\n","filename":"aula.sql","language":"sql","run":"Abra uma sessão nova em memória: sqlite3 :memory:\nNo prompt, use .headers off e .mode list; depois .read aula.sql\nCada exemplo contém sua própria preparação e não depende da aula anterior.","expected":"2|0|56|SEARCH item USING COVERING INDEX ix_categoria (categoria=?)","quiz":{"question":"O plano de uma tabela com duas linhas prova o tempo em produção?","options":["Sim, qualquer plano mede milissegundos exatos.","Não; volume, distribuição e carga precisam ser representativos.","Sim, índices eliminam toda leitura.","Não, porque EXPLAIN apaga dados."],"answer":1,"explanation":"Plano e desempenho medido são evidências distintas."},"exercises":[{"id":1,"title":"Remova o índice e compare o plano","prompt":"Remova o índice e compare o plano.","hint":"DROP INDEX altera as opções de acesso.","solution":"DROP INDEX ix_categoria; rode EXPLAIN QUERY PLAN de novo e procure uma varredura em vez da pesquisa indexada.","criteria":["Registra a estratégia antes e depois sem exigir texto idêntico entre versões.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":2,"title":"Verifique o resultado real da consulta","prompt":"Verifique o resultado real da consulta.","hint":"EXPLAIN não substitui conferir a resposta.","solution":"SELECT id FROM item WHERE categoria='livro'; retorna 1.","criteria":["O resultado permanece correto nos dois planos.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":3,"title":"Descreva um experimento de desempenho reproduzível","prompt":"Descreva um experimento de desempenho reproduzível.","hint":"Fixe consulta, dados e método.","solution":"Registre versão, número e distribuição das linhas, repetições, estado de cache e latências; compare com o mesmo resultado.","criteria":["Inclui carga e método de medição.","Registre o resultado e explique qual regra do banco o produziu."]}],"source":"https://www.sqlite.org/eqp.html","caution":"A saída de EXPLAIN é uma referência da versão usada na revisão; IDs e texto podem variar. Compare a estratégia, não um tempo prometido.","local":true,"hours":4,"minutes":45},{"id":30,"level":10,"title":"Paginação por chave","goal":"Evitar deslocamentos crescentes usando um cursor estável.","theory":[{"title":"Conceito","text":"Paginação por chave solicita linhas posteriores ao último identificador visto. Ela evita depender de contar e pular todas as linhas anteriores."},{"title":"Aplicação","text":"A chave de ordenação precisa ser estável e ter desempate. Se ordenar por data,id, o cursor deve carregar os dois componentes e o predicado deve respeitar a ordem."},{"title":"Verificação","text":"Um cursor não cria automaticamente um retrato estático de todo o banco. Defina o que o usuário deve ver quando novas linhas surgem entre páginas."}],"code":"CREATE TABLE livro(id INTEGER PRIMARY KEY,titulo TEXT);\nINSERT INTO livro VALUES(1,'A'),(2,'B'),(3,'C'),(4,'D');\nSELECT id,titulo FROM livro WHERE id>2 ORDER BY id LIMIT 2;\n","filename":"aula.sql","language":"sql","run":"Abra uma sessão nova em memória: sqlite3 :memory:\nNo prompt, use .headers off e .mode list; depois .read aula.sql\nCada exemplo contém sua própria preparação e não depende da aula anterior.","expected":"3|C\n4|D","quiz":{"question":"Qual é o cursor para pedir a próxima página após o ID 4 nessa ordem?","options":["A quantidade total de colunas.","O nome de qualquer leitor.","O último ID visto, 4.","Sempre zero."],"answer":2,"explanation":"O cursor representa a posição na ordem escolhida."},"exercises":[{"id":1,"title":"Peça a página após id=1","prompt":"Peça a página após id=1.","hint":"Use >1 e mantenha LIMIT 2.","solution":"SELECT id,titulo FROM livro WHERE id>1 ORDER BY id LIMIT 2; retorna 2 e 3.","criteria":["Retorna dois IDs estritamente posteriores ao cursor.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":2,"title":"Explique como paginar por titulo,id","prompt":"Explique como paginar por titulo,id.","hint":"O título pode repetir.","solution":"Use WHERE titulo>:t OR (titulo=:t AND id>:id) com ORDER BY titulo,id e parâmetros nos valores.","criteria":["O cursor carrega título e ID e trata empate.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":3,"title":"Compare inserção de id=0 com cursor id=2","prompt":"Compare inserção de id=0 com cursor id=2.","hint":"O cursor é por valor, não por posição.","solution":"A linha id=0 não desloca a fronteira id>2; ainda assim novas linhas posteriores podem aparecer.","criteria":["Distingue estabilidade da fronteira de snapshot completo.","Registre o resultado e explique qual regra do banco o produziu."]}],"source":"https://www.sqlite.org/lang_select.html","caution":"Laboratório em SQLite; verifique o dialeto ao migrar para outro SGBD. O editor salva o arquivo, mas a execução é local.","local":true,"hours":4,"minutes":45},{"id":31,"level":11,"title":"Parâmetros e aplicação","goal":"Separar a estrutura SQL dos valores fornecidos pelo usuário.","theory":[{"title":"Conceito","text":"Concatenar entrada em SQL mistura dado e sintaxe, permitindo alterar a consulta. Binding envia valores separadamente para que sejam interpretados como dados."},{"title":"Aplicação","text":"Placeholders representam valores, não nomes de tabela ou colunas. Para ordenação dinâmica escolha entre opções permitidas no código; não injete um identificador vindo da entrada."},{"title":"Verificação","text":"O exemplo usa Python como cliente de SQLite e não precisa de servidor. A conexão é fechada explicitamente; consulte o estilo de transação do driver ao adicionar escritas."}],"code":"import sqlite3\ndb = sqlite3.connect(':memory:')\ndb.execute('CREATE TABLE leitor(nome TEXT)')\ndb.executemany('INSERT INTO leitor VALUES(?)', [('Ana',), ('Bia',)])\nentrada = \"Ana' OR 1=1 --\"\nprint(db.execute('SELECT COUNT(*) FROM leitor WHERE nome=?', (entrada,)).fetchone()[0])\ndb.close()\n","filename":"main.py","language":"python","run":"Salve como main.py em uma pasta vazia desta aula. Execute python main.py (ou python3 main.py no Linux/macOS).","expected":"0","quiz":{"question":"Por que a entrada com OR 1=1 não seleciona todos os leitores?","options":["Porque o banco ignora qualquer aspa.","Porque COUNT proíbe ataques automaticamente.","Porque só há duas linhas.","Ela é vinculada como um valor textual, sem virar sintaxe."],"answer":3,"explanation":"O binding separa o comando dos dados."},"exercises":[{"id":1,"title":"Troque entrada por Ana","prompt":"Troque entrada por Ana.","hint":"Mantenha o placeholder e a tupla de um item.","solution":"entrada = 'Ana' faz o programa imprimir 1.","criteria":["O programa imprime 1 sem concatenar SQL.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":2,"title":"Explique a vírgula em (entrada,)","prompt":"Explique a vírgula em (entrada,).","hint":"Parênteses sozinhos não criam uma tupla de um elemento.","solution":"A vírgula cria a sequência de um parâmetro esperada pelo driver; (entrada) seria só a string.","criteria":["Distingue string de tupla de um item.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":3,"title":"Projete ordenação dinâmica por nome ou ID","prompt":"Projete ordenação dinâmica por nome ou ID.","hint":"Nomes de colunas não são valores vinculáveis.","solution":"Use um mapa fixo de opções, por exemplo {'nome':'nome','id':'id'}, rejeite outra chave e só então componha a parte permitida.","criteria":["Aceita apenas os identificadores previstos e mantém valores parametrizados.","Registre o resultado e explique qual regra do banco o produziu."]}],"source":"https://docs.python.org/3/library/sqlite3.html","caution":"Laboratório em SQLite; verifique o dialeto ao migrar para outro SGBD. O editor salva o arquivo, mas a execução é local.","local":true,"hours":4,"minutes":45},{"id":32,"level":11,"title":"Migrações de esquema","goal":"Evoluir o banco com passos versionados e verificáveis.","theory":[{"title":"Conceito","text":"Migração é uma alteração de esquema ou dados registrada com versão e intenção. Scripts avulsos sem histórico tornam ambientes difíceis de comparar."},{"title":"Aplicação","text":"Adicionar coluna pode exigir preencher dados antigos antes de tornar a regra obrigatória. Estratégias expandir, migrar e contrair reduzem ruptura entre versões da aplicação."},{"title":"Verificação","text":"DDL e transações diferem por motor. Neste exemplo SQLite ALTER TABLE ADD COLUMN é transacional, mas essa garantia não deve ser transferida automaticamente ao Oracle ou MySQL."}],"code":"CREATE TABLE livro(id INTEGER PRIMARY KEY,titulo TEXT);\nINSERT INTO livro VALUES(1,'SQL');\nBEGIN; ALTER TABLE livro ADD COLUMN ativo INTEGER NOT NULL DEFAULT 1 CHECK(ativo IN(0,1)); PRAGMA user_version=1; COMMIT;\nSELECT id,titulo,ativo FROM livro; PRAGMA user_version;\n","filename":"aula.sql","language":"sql","run":"Abra uma sessão nova em memória: sqlite3 :memory:\nNo prompt, use .headers off e .mode list; depois .read aula.sql\nCada exemplo contém sua própria preparação e não depende da aula anterior.","expected":"1|SQL|1\n1","quiz":{"question":"Por que a coluna nova possui DEFAULT 1 nesse laboratório?","options":["Para definir um valor válido também para as linhas existentes.","Para apagar o título.","Para transformar a chave em texto.","Para criar um servidor remoto."],"answer":0,"explanation":"Evolução precisa considerar os dados já armazenados."},"exercises":[{"id":1,"title":"Insira livro sem informar ativo","prompt":"Insira livro sem informar ativo.","hint":"O default passa a ser aplicado também na nova escrita.","solution":"INSERT INTO livro(id,titulo) VALUES(2,'Redes'); ativo será 1.","criteria":["A nova linha possui ativo 1.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":2,"title":"Explique o risco de executar a mesma ADD COLUMN duas vezes","prompt":"Explique o risco de executar a mesma ADD COLUMN duas vezes.","hint":"A coluna já existe na segunda tentativa.","solution":"A migração deve consultar e controlar sua versão; repetir o DDL sem mecanismo de histórico causará erro.","criteria":["O processo identifica versões aplicadas.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":3,"title":"Planeje renomear coluna usada por duas versões da API","prompt":"Planeje renomear coluna usada por duas versões da API.","hint":"Evite romper o consumidor antigo durante a transição.","solution":"Adicione nova representação, mantenha compatibilidade, migre leitores/escritores e só remova a anterior depois da troca verificada.","criteria":["Inclui etapas de expansão, migração e contração.","Registre o resultado e explique qual regra do banco o produziu."]}],"source":"https://www.sqlite.org/lang_altertable.html","caution":"Laboratório em SQLite; verifique o dialeto ao migrar para outro SGBD. O editor salva o arquivo, mas a execução é local.","local":true,"hours":4,"minutes":45},{"id":33,"level":11,"title":"Testes de integridade","goal":"Transformar regras e resultados em verificações repetíveis.","theory":[{"title":"Conceito","text":"Um teste de banco deve verificar uma regra observável: ausência de órfãos, total esperado ou rejeição de duplicação. Testes não devem depender da ordem física das linhas."},{"title":"Aplicação","text":"Prepare dados pequenos que distingam os resultados possíveis. Inclua vazio, nulos, duplicados e fronteiras conforme a regra. Isolar cada cenário torna falhas mais fáceis de explicar."},{"title":"Verificação","text":"PRAGMA foreign_key_check e integrity_check têm objetivos próprios no SQLite. Um banco estruturalmente íntegro ainda pode conter um relatório de negócio incorreto."}],"code":"PRAGMA foreign_keys=ON;\nCREATE TABLE livro(id INTEGER PRIMARY KEY,estoque INTEGER NOT NULL CHECK(estoque>=0));\nINSERT INTO livro VALUES(1,2),(2,0);\nSELECT COUNT(*)=2 AS quantidade_ok,MIN(estoque)>=0 AS estoque_ok FROM livro;\nPRAGMA integrity_check;\n","filename":"aula.sql","language":"sql","run":"Abra uma sessão nova em memória: sqlite3 :memory:\nNo prompt, use .headers off e .mode list; depois .read aula.sql\nCada exemplo contém sua própria preparação e não depende da aula anterior.","expected":"1|1\nok","quiz":{"question":"integrity_check=ok prova que a receita do negócio foi calculada corretamente?","options":["Sim, ele conhece qualquer regra do negócio.","Não; integridade estrutural e semântica de negócio são verificações diferentes.","Sim, toda soma passa por esse PRAGMA.","Não, porque ok significa falha."],"answer":1,"explanation":"Regras de domínio precisam de seus próprios testes."},"exercises":[{"id":1,"title":"Crie teste para exatamente um livro sem estoque","prompt":"Crie teste para exatamente um livro sem estoque.","hint":"COUNT com filtro pode ser comparado ao esperado.","solution":"SELECT COUNT(*)=1 FROM livro WHERE estoque=0; retorna 1.","criteria":["A asserção SQL retorna verdadeiro.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":2,"title":"Teste tentativa de estoque negativo em cenário isolado","prompt":"Teste tentativa de estoque negativo em cenário isolado.","hint":"A rejeição é parte do comportamento esperado.","solution":"INSERT INTO livro VALUES(3,-1); deve falhar por CHECK; confirme que a quantidade de linhas permanece 2.","criteria":["A falha e a preservação do estado são verificadas.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":3,"title":"Descreva uma fixture capaz de detectar JOIN que multiplica receita","prompt":"Descreva uma fixture capaz de detectar JOIN que multiplica receita.","hint":"Um pai precisa de mais de um filho.","solution":"Crie cliente com saldo 100 e dois pedidos; a soma correta do saldo do cliente é 100, não 200.","criteria":["A fixture distingue o cálculo correto do incorreto.","Registre o resultado e explique qual regra do banco o produziu."]}],"source":"https://www.sqlite.org/pragma.html","caution":"Laboratório em SQLite; verifique o dialeto ao migrar para outro SGBD. O editor salva o arquivo, mas a execução é local.","local":true,"hours":4,"minutes":45},{"id":34,"level":12,"title":"Backup e restauração","goal":"Criar uma cópia consistente e provar que ela pode ser lida.","theory":[{"title":"Conceito","text":"Backup é uma cópia recuperável; réplica propaga operações e também pode propagar exclusões indesejadas. Defina RPO, perda aceitável de dados, e RTO, tempo aceitável de recuperação."},{"title":"Aplicação","text":"No SQLite, a API de backup coordena uma cópia consistente com o motor. Copiar só o arquivo principal enquanto WAL está ativo pode omitir alterações. O procedimento depende do banco usado."},{"title":"Verificação","text":"Um teste precisa abrir o destino restaurado e conferir dados e integridade. Este exemplo exercita a API em memória; o projeto exige também um arquivo e recuperação em pasta separada."}],"code":"import sqlite3\norigem = sqlite3.connect(':memory:')\ndestino = sqlite3.connect(':memory:')\norigem.execute('CREATE TABLE livro(id INTEGER PRIMARY KEY,titulo TEXT)')\norigem.execute(\"INSERT INTO livro VALUES(1,'SQL')\")\norigem.commit()\norigem.backup(destino)\nprint(destino.execute('SELECT titulo FROM livro').fetchone()[0])\nprint(destino.execute('PRAGMA integrity_check').fetchone()[0])\ndestino.close()\norigem.close()\n","filename":"main.py","language":"python","run":"Salve como main.py em uma pasta vazia desta aula. Execute python main.py (ou python3 main.py no Linux/macOS).","expected":"SQL\nok","quiz":{"question":"Uma réplica substitui automaticamente um backup contra exclusão acidental?","options":["Sim, replicação conserva toda versão para sempre.","Sim, sempre tem retenção ilimitada.","Não; a exclusão também pode ser replicada.","Não, porque réplicas não recebem escritas."],"answer":2,"explanation":"Recuperação exige cópias e pontos de retorno adequados."},"exercises":[{"id":1,"title":"Faça o destino ser arquivo backup-lab","prompt":"Faça o destino ser arquivo backup-lab.db em uma pasta nova.","hint":"Troque apenas a conexão destino.","solution":"sqlite3.connect('backup-lab.db') recebe a cópia; feche e reabra esse arquivo para conferir título e integrity_check.","criteria":["O arquivo reaberto contém SQL e retorna ok.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":2,"title":"Defina RPO de uma hora e RTO de trinta minutos","prompt":"Defina RPO de uma hora e RTO de trinta minutos.","hint":"Um mede perda, o outro tempo de retomada.","solution":"RPO aceita perder no máximo uma hora de dados; RTO exige retomar o serviço em até trinta minutos, com teste que demonstre isso.","criteria":["Distingue perda temporal de duração da recuperação.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":3,"title":"Explique o limite da demonstração em memória","prompt":"Explique o limite da demonstração em memória.","hint":"Ela não testa armazenamento nem retenção.","solution":"A API foi exercitada, mas não houve transferência de arquivo, retenção, desastre nem medição de recuperação operacional.","criteria":["Não apresenta o exemplo como plano de produção validado.","Registre o resultado e explique qual regra do banco o produziu."]}],"source":"https://www.sqlite.org/backup.html","caution":"Laboratório em SQLite; verifique o dialeto ao migrar para outro SGBD. O editor salva o arquivo, mas a execução é local.","local":true,"hours":4,"minutes":45},{"id":35,"level":12,"title":"OLTP, análise e escolha de banco","goal":"Relacionar o modelo de dados ao padrão de acesso.","theory":[{"title":"Conceito","text":"OLTP prioriza operações de negócio frequentes e consistentes; análise agrega grandes conjuntos e histórico. Um mesmo sistema pode atender os dois, mas cargas têm características e custos distintos."},{"title":"Aplicação","text":"Modelo relacional enfatiza relações e restrições; documentos podem agrupar dados lidos juntos; chave-valor atende acessos por chave. NoSQL não significa ausência de esquema, segurança ou transações."},{"title":"Verificação","text":"Escolha a partir de consultas, invariantes, volume, latência, operação e experiência da equipe. Popularidade é um sinal de ecossistema, não uma prova de adequação."}],"code":"CREATE TABLE venda(id INTEGER PRIMARY KEY,dia TEXT,valor_centavos INTEGER);\nINSERT INTO venda VALUES(1,'2026-01-01',100),(2,'2026-01-01',200),(3,'2026-01-02',500);\nSELECT dia,SUM(valor_centavos) FROM venda GROUP BY dia ORDER BY dia;\n","filename":"aula.sql","language":"sql","run":"Abra uma sessão nova em memória: sqlite3 :memory:\nNo prompt, use .headers off e .mode list; depois .read aula.sql\nCada exemplo contém sua própria preparação e não depende da aula anterior.","expected":"2026-01-01|300\n2026-01-02|500","quiz":{"question":"O relatório diário muda a granularidade de venda para quê?","options":["Uma linha por caractere.","Uma linha por banco instalado.","Sempre uma linha por pedido original.","Para uma linha por dia."],"answer":3,"explanation":"O agrupamento define a unidade do indicador."},"exercises":[{"id":1,"title":"Separe duas consultas OLTP e duas analíticas para a biblioteca","prompt":"Separe duas consultas OLTP e duas analíticas para a biblioteca.","hint":"Considere escrita individual e leitura agregada.","solution":"OLTP: registrar empréstimo e confirmar devolução; análise: circulação mensal por categoria e leitores ativos por período.","criteria":["As quatro consultas têm objetivo e granularidade definidos.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":2,"title":"Escolha um banco para app local sem servidor e justifique","prompt":"Escolha um banco para app local sem servidor e justifique.","hint":"Considere implantação embutida e concorrência.","solution":"SQLite é candidato para persistência local; avalie volume de escritas e acesso ao arquivo. A justificativa não deve prometer todo cenário.","criteria":["Relaciona implantação e limites de concorrência.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":3,"title":"Explique por que Redis e MongoDB não são sinônimos","prompt":"Explique por que Redis e MongoDB não são sinônimos.","hint":"Compare unidade de acesso e estrutura principal.","solution":"Redis oferece estruturas acessadas por chaves, frequentemente em memória; MongoDB trabalha com documentos BSON e consultas sobre campos. Ambos exigem modelagem própria.","criteria":["Distingue os modelos sem dizer que NoSQL não tem regras.","Registre o resultado e explique qual regra do banco o produziu."]}],"source":"https://www.sqlite.org/whentouse.html","caution":"Laboratório em SQLite; verifique o dialeto ao migrar para outro SGBD. O editor salva o arquivo, mas a execução é local.","local":true,"hours":4,"minutes":45},{"id":36,"level":12,"title":"Projeto final e revisão técnica","goal":"Entregar um banco reproduzível com consultas, regras e recuperação.","theory":[{"title":"Conceito","text":"O projeto final integra modelagem, escrita transacional, consulta e operação. Um README deve permitir que outra pessoa recrie o laboratório sem estado escondido."},{"title":"Aplicação","text":"Escolha invariantes verificáveis: um exemplar não pode ter dois empréstimos abertos, referências devem existir e repetir a mesma operação não pode duplicar efeitos."},{"title":"Verificação","text":"Apresente evidências de criação, casos inválidos, plano de consulta e restauração. Explique decisões e limites; concluir tarefas não equivale a certificação de administração de produção."}],"code":"PRAGMA foreign_keys=ON;\nCREATE TABLE exemplar(id INTEGER PRIMARY KEY);\nCREATE TABLE emprestimo(id INTEGER PRIMARY KEY,exemplar_id INTEGER NOT NULL REFERENCES exemplar(id),devolvido_em TEXT);\nCREATE UNIQUE INDEX um_aberto ON emprestimo(exemplar_id) WHERE devolvido_em IS NULL;\nINSERT INTO exemplar VALUES(1); INSERT INTO emprestimo VALUES(1,1,NULL);\nSELECT exemplar_id,COUNT(*) FROM emprestimo WHERE devolvido_em IS NULL GROUP BY exemplar_id;\n","filename":"aula.sql","language":"sql","run":"Abra uma sessão nova em memória: sqlite3 :memory:\nNo prompt, use .headers off e .mode list; depois .read aula.sql\nCada exemplo contém sua própria preparação e não depende da aula anterior.","expected":"1|1","quiz":{"question":"Que regra o índice único parcial do exemplo protege?","options":["No máximo um empréstimo aberto por exemplar.","No máximo um empréstimo histórico para sempre.","No máximo um livro no catálogo inteiro.","Exatamente dois empréstimos por exemplar."],"answer":0,"explanation":"A unicidade vale apenas para as linhas que atendem ao predicado do índice."},"exercises":[{"id":1,"title":"Tente segundo empréstimo aberto do exemplar 1","prompt":"Tente segundo empréstimo aberto do exemplar 1.","hint":"O predicado de unicidade inclui ambos.","solution":"INSERT INTO emprestimo VALUES(2,1,NULL); deve falhar; a quantidade de abertos continua 1.","criteria":["A duplicação aberta é rejeitada.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":2,"title":"Registre devolução e depois novo empréstimo","prompt":"Registre devolução e depois novo empréstimo.","hint":"A linha devolvida deixa o índice parcial.","solution":"UPDATE emprestimo SET devolvido_em='2026-01-02' WHERE id=1; INSERT INTO emprestimo VALUES(2,1,NULL); há dois históricos e um aberto.","criteria":["Preserva histórico e permite novo empréstimo.","Registre o resultado e explique qual regra do banco o produziu."]},{"id":3,"title":"Prepare roteiro de demonstração em banco novo","prompt":"Prepare roteiro de demonstração em banco novo.","hint":"Inclua criação, regra inválida e recuperação.","solution":"Execute DDL, fixtures, consultas ordenadas, falha de empréstimo duplo, transação, cópia e reabertura; anexe saídas e explique dialeto/limites.","criteria":["O roteiro pode ser reproduzido sem etapas implícitas.","Registre o resultado e explique qual regra do banco o produziu."]}],"source":"https://www.sqlite.org/partialindex.html","caution":"Laboratório em SQLite; verifique o dialeto ao migrar para outro SGBD. O editor salva o arquivo, mas a execução é local.","local":true,"hours":4,"minutes":45}]};
